WITH payload AS (SELECT $archive_payload$[{"id":"2fe1294b-c8db-5d2e-bebf-a447e5d3133b","document_type":"judgment","category":"judicial","subcategory":"general","title":"تشبه بالنساء -شذوذ جنسي -لواط -فعل الفاحشة -جتهيز صالون حالقة للرجال بغرض فعل اللواط -اعتداء على رجال الضبط -مساحيق نسائية -أدوات منافية لألخاق -صور ملمارسة الشذوذ باجلوال -إدانة -تعزير بالسجن واجللد .","document_number":"34186223","case_number":"33567132","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/13","year":"1434","subject":"تشبه بالنساء -شذوذ جنسي -لواط -فعل الفاحشة -جتهيز صالون حالقة للرجال بغرض فعل اللواط -اعتداء على رجال الضبط -مساحيق نسائية -أدوات منافية لألخاق -صور ملمارسة الشذوذ باجلوال -إدانة -تعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫رقم الصك‪ 34186223 :‬تاريخه‪1434/3/13 :‬هـ‬\n                      ‫رقم الدعوى‪33567132 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 34239149‬تاريخه‪1434/6/12 :‬هـ‬\n\n\n    ‫تشــبه بالنســاء ‪ -‬شــذوذ جنســي ‪ -‬لــواط ‪ -‬فعــل الفاحشــة ‪ -‬جتهيــز‬\n    ‫صالــون حالقــة للرجــال بغــرض فعــل اللــواط ‪ -‬اعتــداء علــى رجــال‬\n    ‫الضبــط ‪ -‬مســاحيق نســائية ‪ -‬أدوات منافيــة لألخــاق ‪ -‬صــور ملمارســة‬\n                     ‫الشــذوذ باجلــوال ‪ -‬إدانــة ‪ -‬تعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n\n                                           ‫ما ذكره القاضي يف تسبيب حكمه ‪.‬‬\n\n\n\n\n    ‫ادعــى املدعــي العــام علــى املدعــى عليــه بقيامــه بالتشــبه بالنســاء ونــزع‬\n    ‫شــعر صــدره ويديــه واإلســتعداد ملمارســة الرذيلــة واالعتــداء علــى رجــال‬\n    ‫األمــر باملعــروف والنهــي عــن املنكــر وحيازتــه بجوالــه صــور ًا جنســية‬\n                                   ‫مشــينة وطلــب معاقبتــه بتعزيــره لقــاء ذلــك ‪.‬‬\n    ‫ومبواجهــة املدعــى عليــه بذلــك أنكــر التشــبه بالنســاء وممارســته‬\n    ‫الشــذوذ وأقــر باحتــواء جوالــه علــى صــور فاضحــة أخذهــا مــن النــت ‪.‬‬\n    ‫وبعــد أن وازنــت احملكمــة بــن أقــوال وأســانيد الطرفــن قــررت تعزيــره‬\n    ‫بســجنه عــام ونصــف وجلــده مائــة وخمســون جلــدة وأخــذ التعهــد عليــه‬\n    ‫وقــد اعتــرض املدعــي العــام وقنــع املدعــى عليــه وجــرى التصديــق مــن‬\n                                                            ‫محكمــة االســتئناف ‪.‬‬\n‫‪9‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...............‬القاضــي يف احملكمــة‬\n‫اجلزائيــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمة اجلزائية بالرياض برقم ‪ 33567132‬وتاريخ ‪1433/09/09‬هـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 331673576‬وتاريــخ ‪ 1433/09/09‬ه ـ ففــي‬\n‫يــوم االثنــن املوافــق‪ 1433/10/23‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 15‬‬\n‫وفيهــا حضــر املدعــي العــام ‪ ......‬وقــدم دعــواه علــى ‪28 ،.............. /‬عاما‬\n‫‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )............‬غيــر محصــن‬\n‫‪ ،‬متعلــم ‪ ،‬يقيــم مبدينــه الريــاض ‪ ،‬موظــف حكومــي ‪ ،‬صــدر بحقــه‬\n‫أمــر توقيــف رقــم ه ـ ر‪ 87301/1‬وتاريــخ ‪1433/8/15‬ه ــو وأمــر متديــد‬\n‫توقيــف رقــم ه ـ ر‪ 88652/3/1‬وتاريــخ ‪1433/8/19‬ه ـ اســتنادا للمــادة‬\n‫(‪ )113‬مــن نظــام اإلجــراءات اجلزائيــة‪ .‬قائــا يف دعــواه عليــه إنــه بتاريــخ‬\n‫‪1433/8/14‬ه ـ قبــض علــى املذكــور مــن قبــل هيئــة األمــر باملعــروف‬\n‫و النهــي عــن املنكر‪/‬وحــدة العمليــات امليدانيــة بعــد أن توفــرت لديهــم‬\n‫معلومــات عــن صالــون للحالقــة الرجاليــة يقــوم بتجهيــز الشــاذين جنســيا‬\n‫و بالتوجــه للموقــع شــوهد املذكــور خارجــا مــن الصالــون وتظهــر عليــه‬\n‫عالمــات التكســر و التميــع و عنــد مشــاهدته للفرقــة حــاول الهــرب‬\n‫علــى أقدامــه فتــم ضبطــه بعــد أن قــاوم الفرقــة مقاومــة شــديدة وتعــدى‬\n‫علــى احــد األعضــاء بالضــرب و مــزق ثــوب عضــو ًا آخــر وبصــق يف وجــه‬\n‫عض ـ ٍو ثالــث ‪ ،‬وكان حالق ـ ًا لشــعر صــدره ويديــه وضبــط بحوزتــه‬\n‫حــزام وحــذاء ونظــارات وعطــور نســائية وتبــن للفرقــة أنــه مت القبــض‬\n‫عليــه عــدة مــرات يف قضيــة مماثلــة‪ ،‬علــى اثــر ذلــك مت ضبــط عامــل‬\n\n                                                                                      ‫‪10‬‬\n\f     ‫احلالقــة بســبب قيامــه بتجهيــز الشــواذ ‪ ،‬مت حفــظ الدعــوى بحقــه لعــدم‬\n     ‫ثبــوت األدلــة‪ .-‬وبفحــص جــوال املذكــور مــن قبــل الفرقــة مت العثــور‬\n     ‫علــى مجموعــة مــن الصــور العائــدة إليــه وهــو يضــع مســاحيق التجميــل‪،‬‬\n     ‫وصــور أخــرى ميــارس فيهــا الشــذوذ اجلنســي وصــور ألعضــاء تناســلية‬\n     ‫ذكريــة‪ ،‬كمــا عثــر علــى مقاطــع فيديــو ميــارس فيهــا الشــذوذ والعــادة‬\n     ‫الســرية و بإجــراء املشــاهدة للمذكــور مــن قبــل جهــة التحقيــق‪ /‬تبــن‬\n     ‫أنــه حالقــا لشــعر صــدره و علــى وجهــه آثــار مســاحيق التجميل و مســرح ًا‬\n     ‫لشــعر رأســه و تظهــر عليــه عالمــات التميــع‪ .‬وبســماع أقــوال املذكــور‬\n     ‫واســتجوابه ‪/‬اقــر بأنــه كان خارجــا مــن صالــون احلالقــة و أن هــذه‬\n     ‫هــي املــرة الثانيــة التــي يقبــض عليــه فيهــا مــن قبــل الهيئــة بنفــس التهمــة‬\n     ‫وأســفرت إجــراءات التحقيــق ‪ /‬عــن اتهــام املذكــور بالتشــبه بالنســاء و‬\n     ‫مقاومــة الفرقــة وحيــازة هاتــف جــوال يحتــوي علــى صــور و مقاطــع فيديو‬\n                          ‫ميــارس فيهــا الشــذوذ‪ .‬وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n                  ‫‪ .1‬ما جاء مبحضر القبض املعد من الفرقة القابضة لفه (‪)3‬‬\n                   ‫‪ .2‬ما جاء مبحضر املشاهدة املدون بدفتر التحقيق لفه (‪)8‬‬\n     ‫‪ .3‬مــا جــاء يف محضــر الكشــف علــى جــوال املذكــور املعــد مــن فرقــة‬\n                                                                            ‫القبــض لفــه (‪)2‬‬\n                       ‫‪ .4‬ما جاء يف أقوال األول املدونة بدفتر التحقيق لفه (‪)8‬‬\n     ‫وببحــث ســوابقه اتضــح خلــو ســجله‪ .‬وحيــث إن مــا أقــدم عليــه املذكــور‬\n     ‫فعــل محــرم ومعاقــب عليــه شــرعا أطلــب إثبــات مــا أســند إليــه واحلكــم‬\n     ‫عليــه بعقوبــة تعزيريــة لقــاء مــا أســند إليــه‪ .‬علم ـ ًا بــأن أعضــاء الفرقــة‬\n     ‫يطالبــون بحقهــم اخلــاص‪ .‬وبــاهلل التوفيــق ‪ .‬وبعــرض دعــوى املدعــي العــام‬\n     ‫علــى املدعــى عليــه ‪ .........‬ســعودي بالهويــة رقــم ‪ .............‬أجــاب بقولــه مــا‬\n\n\n‫‪11‬‬\n\f‫جــاء يف دعــوى املدعــي العــام كلــه غيــر صحيــح فأنــا لــم أقــم بالتشــبه‬\n‫بالنســاء ولــم أقــم بحلــق شــعر صــدري وذراعــي ولــم أقــم بوضــع أي‬\n‫مســاحيق علــى وجهــي وكــذا ال صحــة ملــا جــاء يف دعــوى املدعــي العــام‬\n‫مــن وجــود صــور لــي وأنــا أقــوم بوضــع مســاحيق علــى وجهــي ومــا جــاء‬\n‫يف الدعــوى مــن العثــور علــى صــور ميــارس فيهــا الشــذوذ اجلنســي وصــور‬\n‫ألعضــاء ذكريــة فصحيــح وأنــا قمــت بســحبها مــن النــت وأنــا نــادم علــى‬\n‫ذلــك هكــذا أجــاب وبعــرض ذلــك علــى املدعــي العــام أجــاب بقولــه‬\n‫أطلــب الرجــوع للمعاملــة لإلطــاع علــى مــا جــاء فيهــا مــن أدلــة وقرائــن‬\n‫وبالرجــوع للمعاملــة وجــد فيهــا محضــر القبــض لفــة رقــم (‪ )3‬الصــادر‬\n‫مــن وحــدة العمليــات يف هيئــة األمــر باملعــروف والنهــي عــن املنكــر‬\n‫ونــص احلاجــة منــه « توفــرت لدينــا معلومــات عــن صالــون حالقــة يقــوم‬\n‫بتجهيــز الشــاذين جنســيا ويف هــذا اليــوم جتــددت املعلومــات عــن وجــود‬\n‫شــاب تظهــر عليــه عالمــات التكســر والتميــع حضــر للصالــون وقــام‬\n‫عامــل الصالــون بتجهيــزه وعنــد االنتقــال للموقــع شــاهدنا املذكــور‬\n‫أعــاه خارجــا مــن الصالــون وتظهــر عليــه عالمــات التكســر والتميــع‬\n‫وعنــد مشــاهدته للفرقــة حــاول الهــرب علــى أقدامــه فتــم ضبطــه بعــد‬\n‫مقاومــة شــديدة للفرقــة وقــام بضــرب أحــد أعضــاء الفرقــة ومــزق ثــوب‬\n‫العضــو اآلخــر وقــام بالبصــق يف وجــه الثالــث وقــد تبــن بعــد الضبــط‬\n‫أنــه حالــق شــعر صــدره وشــعر يديــه وقــد ضبــط عامــل احملــل الــذي يقــوم‬\n‫بتجهيــز الشــاذين جنســيا وقــد ضبــط يف حــوزة الشــاذ حــزام نســائي‬\n‫وجزمــة نســائية ونظــارات نســائية وكذلــك يحمــل عطــورات نســائية»‬\n‫ف أهــ‪ .‬وبعــرض احملضــر علــى املدعــى عليــه أجــاب بقولــه ال صحــة ملــا‬\n‫جــاء يف احملضــر بخصــوص التشــبه واملســاحيق وحلــق شــعر صــدري‬\n\n\n                                                                                   ‫‪12‬‬\n\f     ‫ومــا جــاء يف احملضــر مــن املقاومــة فصحيــح فقــد دخلــوا علــي يف محــل‬\n     ‫احلالقــة وطلبــوا منــي اخلــروج فرفضــت لكونهــم ال يحملــون أي صفــة‬\n     ‫كمــا إن ســيارتهم ليســت رســمية ثــم ملــا خرجــت مــن الصالــون وحتققــت‬\n     ‫مــن كونهــم أعضــاء هيئــة األمــر باملعــروف والنهــي عــن املنكــر ســلمت‬\n     ‫نفســي لهــم هكــذا أجــاب ورفعــت اجللســة لطلــب أعضــاء الهيئــة وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                            ‫حــرر يف ‪1433/10/23‬ه ـ‬\n     ‫ويف يــوم األحــد ‪1433/11/28‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n     ‫العــام أمــا املدعــى عليــه فلــم يحضــر وقــد جــرى طلبــه مــن الســجن العــام‬\n     ‫فلــم يتــم إحضــاره وقــد أحضــر املدعــي العــام شــاهدا ويطلــب ســماع مــا‬\n     ‫لديــه هــذا وقــد حضــر ‪ ...........‬ســعودي بالهويــة رقــم ‪ ..........‬مــن مواليــد‬\n     ‫‪1405/4/17‬ه ـ ويعمــل يف هيئــة األمــر باملعــروف والنهــي عــن املنكــر‬\n     ‫فرقــة العمليــات وبســؤاله اجــاب بقولــه أشــهد بــاهلل أنــه توفــرت معلومات‬\n     ‫لدينــا عــن قيــام املدعــى عليــه ‪ ..........‬بعــرض نفســه علــى الشــباب وقــد‬\n     ‫مت التنســيق مــع أحــد املصــادر وجــرى االتصــال بــه وقــام بإرســال صــور‬\n     ‫جلســمه وهــو عــار ثــم بعــد ذلــك جــرى متابعــة أحــد صوالــن احلالقــة التــي‬\n     ‫توفــرت معلومــات أنــه يقــوم بتجهيــز الشــاذين جنســيا وأثنــاء متابعــة‬\n     ‫هــذا احملــل شــاهدنا املدعــى عليــه ‪ ........‬يدخــل الصالــون ثــم خــرج بعــد‬\n     ‫ذلــك وكان ميشــي مشــية نســاء وملــا شــاهدنا قــام بالهــروب فتــم متابعتــه‬\n     ‫والقبــض عليــه وقــد قــاوم الفرقــة القابضــة مقاومــة شــديدة وذهبــت أثناء‬\n     ‫ذلــك إلــى الصالــون للقبــض علــى العامــل وبعــد القبــض علــى املدعــى‬\n     ‫عليــه اتضــح لنــا بأنــه كان حالقــا جلميــع شــعر جســمه وقــد جــرى ضبــط‬\n     ‫جهــازه اجلــوال وعثــر فيــه علــى مجموعــة مــن الصــور عائــدة للمدعــى‬\n\n\n‫‪13‬‬\n\f‫عليــه وهــو واضــع مســاحيق التجميــل علــى وجهــه وكــذا مقاطــع وصــور‬\n‫متــارس فيهــا الشــذوذ اجلنســي وغيرهــا مــن املقاطــع والصــور اإلباحيــة‬\n‫واهلل علــى مــا أقــول شــهيد ورفعــت اجللســة لطلــب املدعــى عليــه وعــرض‬\n           ‫الشــهادة عليــه إلــى يــوم االثنــن ‪1433/11/29‬ه ـ واهلل املوفــق ‪.‬‬\n‫ويف يــوم األحــد ‪1434/3/22‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n‫العــام وقــد احضــر املدعــي العــام شــاهدا ويطلــب ســماع مــا لديــه هــذا‬\n‫وقــد حضــر ‪ ..............‬ســعودي بالهويــة ‪ .........‬يعمــل يف هيئــة األمــر‬\n‫باملعــروف والنهــي عــن املنكــر يف مركــز العمليــات مــن مواليــد‬\n‫‪1411/3/11‬ه ـ وبســؤاله أجــاب بقولــه أشــهد بــاهلل أنــه أثنــاء قيامنــا‬\n‫بعملنــا شــاهدنا املدعــى عليــه ‪ ..........‬خارجـ ًا مــن محــل حالقــة يف شــمال‬\n‫الريــاض فلمــا شــاهدنا قــام بالهــرب إلــى داخــل احلــي وملــا مت اإلمســاك‬\n‫بــه قــام بالبصــق علــى أحــد األعضــاء واملقاومــة الشــديدة ثــم الســيطرة‬\n‫عليــه وكان املدعــى عليــه يحمــل شــنطة بداخلهــا نظــارة نســائية وعطــر‬\n‫نســائي وحــزام نســائي ولــم ندخــل محــل احلالقــة مطلقــا واهلل علــى مــا‬\n‫أقــول شــهيد‪ .‬ثــم إن املدعــي العــام طلــب مهلــة أخــرى إلحضــار زيــادة بينــة‬\n‫فأجيــب لطلبــه ورفعــت اجللســة لطلــب املدعــى عليــه وعــرض الشــهادة‬\n                   ‫عليــه ‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n‫ويف يــوم األحــد ‪1434/3/29‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n‫العــام وحضــر حلضــوره املدعــى عليــه وبعــرض شــهادة الشــاهدين علــى‬\n‫املدعــى عليــه أجــاب بقولــه مــا جــاء يف شــهادة الشــاهدين فغيــر صحيــح‬\n‫وكل مــا يف األمــر أنــي كنــت خارجــا مــن محــل حالقــة فتوقــف أمامــي‬\n‫ســيارة ‪ ....‬ونــزل منهــا ثالثــة أشــخاص وطلبــوا منــي الذهــاب معهــم‬\n‫فرفضــت لكونــي ال أعرفهــم فقامــوا بســحبي وقامــوا بإركابــي‬\n\n\n                                                                                      ‫‪14‬‬\n\f     ‫ب‪ ......‬ومــن ثــم ذهبــوا بــي لداخــل احلــي ثــم حضــرت ســيارة رســمية‬\n     ‫تابعــة للهيئــة وقامــوا بإركابــي بالقــوة وأنــا كنــت أقاومهــم لعــدم‬\n     ‫معرفتــي بأنهــم رجــال هيئــة وال صحــة ملــا جــاء يف شــهادة الشــاهدين مــن‬\n     ‫العثــور علــى أدوات نســائية معــي هكــذا أجــاب فبنــاء علــى مــا تقــدم‬\n     ‫مــن دعــوى املدعــي العــام وإجابــة املدعــى عليــه وحيــث أنكــر املدعــى‬\n     ‫عليــه قيامــه بالتشــبه بالنســاء وحيــث أحضــر املدعــي العــام شــاهدين‬\n     ‫مــن أعضــاء هيئــة األمــر باملعــروف والنهــي عــن املنكــر شــهد أحدهمــا‬\n     ‫بقيــام املدعــى عليــه بالتشــبه بالنســاء ووضــع مســاحيق جتميــل وحلــق‬\n     ‫جميــع شــعر جســمه وشــهد اآلخــر بوجــود شــنطة نســائية بحــوزة املدعــى‬\n     ‫عليــه بداخلهــا أغــراض نســائية وحيــث أن مــا جــاء يف شــهادة الشــاهدين‬\n     ‫يــورث الشــبهة القويــة جتاهــه وحيــث أنكــر املدعــى عليــه مقاومــة‬\n     ‫رجــال احلســبة وحيــث شــهد الشــاهدين املذكوريــن بعاليــه علــى قيــام‬\n     ‫املدعــى عليــه بذلــك وحيــث اعتــرف املدعــى عليــه باحتــواء جهــازه اجلــوال‬\n     ‫ملقاطــع إباحيــة فعليــه فقــد ثبــت لــدي مقاومــة املدعــى عليــه لرجــال‬\n     ‫هيئــة األمــر باملعــروف والنهــي عــن املنكــر مقاومــة شــديدة واحتــواء‬\n     ‫جهــازه اجلــوال ملقاطــع إباحيــة وتوجــه الشــبهة القويــة جتــاه املدعــى عليــه‬\n     ‫بالتشــبه بالنســاء وعــرض نفســه علــى الشــباب وقــررت تعزيــره لقــاء‬\n     ‫ذلــك بســجنه ســنة وســتة أشــهر مــن تاريــخ إيقافــه وجلــده مائــة وخمســن‬\n     ‫جلــدة مفرقــة علــى ثــاث دفعــات كل دفعــة خمســون جلــدة بــن كل‬\n     ‫دفعــة وأخــرى عشــرة أيــام وأخــذ التعهــد عليــه بعــدم العــودة ملــا بــدر منــه‬\n     ‫وبذلــك حكمــت وبعرضــه علــى املدعــي العــام قــرر االعتــراض مكتفيــا‬\n     ‫بالئحــة الدعــوى أمــا املدعــى عليــه فقــد قــرر القناعــة باحلكــم واهلل‬\n     ‫املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‬\n\n\n‫‪15‬‬\n\f                                                    ‫‪ .‬حــرر يف ‪1434/3/29‬ه ـ‬\n‫احلمــد هلل وحــده أطلــع قضــاة الدائــرة اجلزائيــة األولــى علــى املعاملــة‬\n‫الــواردة مــن احملكمــة اجلزائيــة بالريــاض برقــم ‪ 331673576‬وتاريــخ‬\n‫‪1434/4/22‬ه ـ واملرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫‪ ............./‬برقــم ‪ 34186223‬وتاريــخ ‪1434/4/13‬ه ـ واخلــاص بدعــوى‬\n‫املدعــي العــام ضــد ‪ ................./‬وموضوعهــا شــذوذ جنســي وانتهــاء‬\n‫الدراســة والتدقيــق باملصادقــة علــى احلكــم لعــدم موجــب املالحظــة‬\n                              ‫وصلــى اهلل علــى نبينــا محمــد واهلل املوفــق ‪.‬‬\n\n\n\n\n                                                                                  ‫‪16‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":9,"source_page_end":16,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"519d6bae7c23a367f34093f956950cb7b656c8a713a0682c90db109a674cb102","normalized_text_hash":"fcd8688fbc206cc0069c126202c3db710a8fda544ae010645278257bc67f0619","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p9-34186223"},{"id":"7206ed15-3320-5a7b-b317-0f13476a871f","document_type":"judgment","category":"judicial","subcategory":"general","title":"تشبه بالنساء -شذوذ جنسي -أدوات نسائية -عطر نسائي - مالبس نسائية يف حيازته -صور فاضحة على اجلوال -إدانة - تعزير باجللد واحلبس.","document_number":"34276758","case_number":"34315880","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملذنب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/23","year":"1434","subject":"تشبه بالنساء -شذوذ جنسي -أدوات نسائية -عطر نسائي - مالبس نسائية يف حيازته -صور فاضحة على اجلوال -إدانة - تعزير باجللد واحلبس.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 34276758 :‬تاريخه‪1434/7/23 :‬هـ‬\n                        ‫رقم الدعوى‪34315880 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34336588‬تاريخه‪1434/11/18 :‬هـ‬\n\n\n     ‫تشــبه بالنســاء ‪ -‬شــذوذ جنســي ‪ -‬أدوات نســائية ‪ -‬عطــر نســائي ‪-‬‬\n     ‫مالبــس نســائية يف حيازتــه ‪ -‬صــور فاضحــة علــى اجلــوال ‪ -‬إدانــة ‪-‬‬\n                                                  ‫تعزيــر باجللــد واحلبــس‪.‬‬\n\n\n\n\n     ‫قولــه صلــى اهلل عليــه وســلم «لعــن اهلل املتشــبهني مــن الرجــال بالنســاء‬\n                                            ‫واملتشــبهات مــن النســاء بالرجــال»‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي العــام علــى املدعــى عليــه بقيامــه بوضــع مســاحيق نســائية‬\n     ‫والتشــبه بالنســاء حيــث قبــض عليــه مبعرفــة رجــال الضبــط وعثــر معــه‬\n     ‫يف جوالــه علــى صــور خليعــة وطلــب تعزيــره وســجنه وتغرميــه ومصــادرة‬\n     ‫جهــازه النقــال‪ .‬ومبواجهــة املدعــى عليــه بذلــك أنكــر التشــبه بالنســاء‬\n     ‫وعــدم معرفتــه مبــا يحتويــه اجلهــاز النقــال‪ .‬وبعــد أن وازنــت احملكمــة‬\n     ‫بــن أقــوال وأســانيد الطرفــن قــررت تعزيــره باجللــد ثالثمائــة جلــدة‬\n     ‫والســجن عشــرون يومـ ًا ومصــادرة اجلــوال واعتــرض املدعــي العــام وجرى‬\n                            ‫التصديــق مــن محكمــة االســتئناف بعــد التعديــل‪.‬‬\n\n\n\n\n‫‪17‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬رئيــس احملكمــة العامــة‬\n‫باملذنــب وبنــاء علــى املعاملــة الــواردة إلينــا مــن التحقيــق واالدعــاء العــام‬\n‫مبحافظــة املذنــب برقــم ه ـ ص ‪ 765/2/4‬املقيــدة باحملكمــة برقــم‬\n‫‪ 341638155‬وتاريــخ ‪ 1434/07/08‬ه ـ احملالــة لنــا برقــم ‪34315880‬‬\n‫وتاريــخ ‪ 1434/07/09‬ه ـ ففــي يــوم االثنــن املوافــق‪ 1434/07/17‬ه ـ‬\n‫افتتحــت اجللســة الســاعة العاشــرة صباحــا وفيهــا حضــر املدعــي العــام‬\n‫ا بصفتــي مدعي ـ ًا عام ـ ًا يف دائــرة التحقيــق واالدعــاء‬      ‫‪ ......‬وادعــى قائ ـ ً‬\n                                        ‫العــام مبحافظــة املذنــب أدعــي علــى ‪:‬‬\n‫‪ ، ......‬البالــغ مــن العمــر (‪ ) 21‬عامـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب الهويــة‬\n‫الوطنيــة رقم‪......‬أعــزب ‪ ،‬متعلــم ‪ ،‬طالــب ‪ ،‬يقيــم يف محافظــة املذنــب‬\n‫‪ ،‬أوقــف بتاريــخ ‪1434/6/15‬ه ـ وأفــرج عنــه بتاريــخ ‪1434/6/18‬ه ـ‬\n‫؛ اســتنا ًدا للمــادة (‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة‪ .‬بالكفالــة‬\n                                                                ‫احلضوريــة املرفقــة‪.‬‬\n‫ـاء وأثنــاء‬\n          ‫فإنــه بتاريــخ ‪1434/6/15‬ه ـ الســاعة التاســعة والنصــف مسـ ً‬\n‫قيــام فرقــة ميدانيــة تابعــة لهيئــة األمــر باملعــروف والنهــي عــن املنكــر‬\n‫مبحافظــة عنيــزة (مركــز هيئــة ‪ )......‬بعملهــم يف مخطــط ‪ ......‬شــاهدوا‬\n‫املدعــى عليــه املذكــور وهــو متوقــف بســيارته مــن نــوع ‪ ......‬لوحــة رقــم‬\n‫(‪ )......‬وبالتوقــف بجــواره بــدت عليــه مظاهــر اخلــوف واالرتبــاك وشــوهد‬\n‫واضع ـ ًا للمكيــاج النســائي (كــرمي أســاس باإلضافــة لــروج الشــفاه)‬\n‫ومشــقر ًا حلاجبيــه البسـ ًا عدســات ملونــة الصقــة بعينيــه متعطــر ًا بعطــر‬\n‫نســائي متشــبه ًا بالنســاء يف لباســه وعثــر بجهــازه النقــال علــى صــورة‬\n\n                                                                                           ‫‪18‬‬\n\f     ‫شــخصية لــه ملصقـ ًا شــفتيه بشــفتي شــخص آخــر وصــورة أخــرى لعضــو‬\n     ‫ذكــري وعــدد مــن الصــور اخلالعــة كمــا عثــر بحوزتــه علــى علبــة‬\n     ‫مكيــاج ملــون وكــرمي أســاس وزجاجــة عطــر نســائي ومثبــت للشــعر مــن‬\n     ‫نــوع (‪ )......‬وشــال نســائي وبســؤالهم لــه أفــاد بأنــه علــى موعــد مــع شــاب‬\n                                                            ‫آخــر فتــم القبــض عليــه‪.‬‬\n     ‫وبســماع أقوالــه أقـ ّـر بصحــة واقعــة القبــض عليــه لقــاء قيامــه بوضــع‬\n                                            ‫مكيــاج علــى وجهــه لغــرض الزينــة‪.‬‬\n     ‫وباستج ــوابه أقـ ّـر بصحــة واقع ــة القبــض عليــه مــن قبــل رجــال هيئة األمر‬\n     ‫باملعــروف والنهــي عــن املنكــر حينمــا كان متوقف ـ ًا بســيارته مــن نــوع‬\n     ‫‪ ......‬صنــع عــام ‪2012‬م لوحــة رقــم (‪ )......‬مبخطــط ‪ ......‬مبحافظــة عنيــزة‬\n     ‫وكان يرتــدي بنطــال وفانيلــة واضعـ ًا للمكيــاج وروج الشــفاه وعدســات‬\n     ‫الصقــة بعينيــه وتعطــره بعطــر نســائي وأنــه علــى موعــد مــع أحــد زمالئــه‬\n     ‫وأن‬\n      ‫بالدراســة وتبادلــه مــع شــخص مــن أقاربــه للقبــات مــن أهالــي ‪ّ ......‬‬\n     ‫الصــور اخلالعــة وصــورة العضــو الذكــري قــام بتحميلهــا مــن اإلنترنــت‬\n     ‫ومــا يختــص باملضبوطــات مــن مثبــت الشــعر ‪ ......‬وكــرمي األســاس‬\n     ‫والشــال النســائي فهــي عائــدة إلحــدى شــقيقاته وبعائديــه الكاميــرا‬\n     ‫مــن نــوع ‪......‬موديــل ‪ ......‬لــه شــخصي ًا وحتتــوي علــى صــور شــخصية لــه‬\n     ‫ولعائلتــه وزمالئــه وصــادق علــى إقــراره بذلــك منكــر ًا تشــقير حاجبيــه‬\n                                                          ‫وارتدائــه ملالبــس نســائية‪.‬‬\n     ‫وقــد أســفر التحقيــق معــه عــن توجيــه االتهــام لــه بالتشــبه بالنســاء‬\n     ‫والتوقــف مبــكان منــزو بســيارته ملقابلــة أحــد األشــخاص لغــرض ســيء‬\n     ‫ومتكــن شــخص آخــر مــن تقبيلــه علــى شــفتيه وتخزينــه صــور مخلــة‬\n     ‫بــاآلداب العامــة بجهــازه النقــال مــن أحــد مواقــع الشــبكة املعلوماتيــة‪.‬‬\n\n\n‫‪19‬‬\n\f                                                   ‫وذلك لألدلة والقرائن التالية‪:‬‬\n‫‪ .1‬إقــراره املنــوه عنــه املــدون علــى الصفحــة رقــم (‪ )1‬مــن دفتــر محاضــر‬\n                                                   ‫التحقيــق املرفــق لفــة رقــم (‪)8‬‬\n‫‪ .2‬مــا جــاء بســماع أقوالــه املنــوه عنــه املــدون علــى الصفحــة رقــم (‪ )2‬مــن‬\n     ‫ملــف اســتكمال محاضــر إجــراءات االســتدالل املرفــق لفــة رقــم (‪)1‬‬\n‫‪ .3‬محضــر القبــض املنــوه عنــه املعــد مــن قبــل مركــز هيئــة ‪ ......‬لألمــر‬\n            ‫باملعــروف والنهــي عــن املنكــر باحملافظــة املرفــق لفــة رقــم (‪)2‬‬\n‫‪ .4‬املضبوطــات املنــوه عنهــا واملدونــة يف محضــر القبــض املرفــق لفــة رقــم‬\n                                                                            ‫(‪)16 -15‬‬\n‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه املذكــور فعــل محــرم شــرع ًا‬\n‫ومجــرم نظام ـ ًا مبوجــب نظــام مكافحــة جرائــم املعلوماتيــة الصــادر‬\n‫باملرســوم امللكــي رقــم (م‪ )17/‬وتاريــخ ‪1428/3/8‬ه ـ ومعاقــب عليــه‬\n‫شــرعا ونظام ـ ًا لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه‬\n                                                                 ‫بالعقوبــات التاليــة‪:‬‬\n                                        ‫أوالً‪ :‬بعقوبة تعزيرية تزجره وتردع غيره‪.‬‬\n‫ثاني ـاً‪ :‬بالســجن والغرامــة أو بإحــدى هاتــن العقوبتــن وفق ـ ًا للفقــرة‬\n‫األولــى (‪ )1‬مــن املــادة (‪ )6‬السادســة مــن نظــام مكافحــة جرائــم‬\n                                                            ‫املعلوماتيــة املشــار لــه‪.‬‬\n‫ثالثـاً‪ :‬مبصــادرة جهــاز هاتفــه النقــال املوصــوف وفقـ ًا للمــادة (‪ )13‬الثالثة‬\n                                              ‫عشــرة مــن ذات النظــام املشــار إليه‬\n‫هــذه دعــواي واســأل املدعــى عليــه اجلــواب وبســؤال املدعــى عليــه عــن‬\n‫الدعــوى أجــاب بقولــه نعــم لقــد قبــض علــي مــن قبــل مركــز هيئــة ‪......‬‬\n‫مبحافظــة عنيــزة وكنــت البســا بنطلونــا أســود وفانيلــة خضــراء ولــم‬\n\n\n                                                                                           ‫‪20‬‬\n\f     ‫أكــن واضعـ ًا للمكيــاج ولــم أشــقر حاجبــي ولــم أكــن البســا عدســات‬\n     ‫الصقــة ولــم أتعطــر بعطــر نســائي والصــورة الشــخصية املوجــودة يف‬\n     ‫جوالــي هــي صورتــي وقــد يدخلهــا الدبلجــة والصــور املوجــودة باجلهــاز‬\n     ‫ال أعلــم عنهــا ألننــي اشــتريت اجلهــاز وال أعلــم مــا يوجــد بــه واألغــراض‬\n     ‫املوجــودة يف الســيارة ال تعــود لــي وإمنــا لعائلتــي وال أوافــق علــى مــا طلبــه‬\n     ‫املدعــي العــام هــذه إجابتــي ورفعــت اجللســة إلــى يــوم األحــد املوافــق‬\n     ‫‪1434/7/23‬ه ـ الســاعة احلاديــة عشــرة صباحــا وبــاهلل التوفيــق ‪،‬‬\n     ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                        ‫‪1434/7/17‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم األحــد املوافق‪1434/07/23‬ه ـ‬\n     ‫الســاعة احلاديــة عشــره افتتحــت اجللســة بحضــور املدعــي العــام واملدعــى‬\n     ‫عليــه ‪ ......‬ثــم جــرى ســؤال املدعــي العــام هــل لديــك بينــة علــى دعــواك‬\n     ‫؟ فأجــاب بقولــه نعــم وهــي مــا ذكرتــه يف الئحــة الدعــوى واملعاملــه‬\n     ‫وقــد جــرى الرجــوع إلــى املعاملــه ومت األطــاع علــى اقــرار املدعــى عليــه‬\n     ‫ص‪1‬مــن ملــف التحقيــق لفــة رقــم ‪ 8‬وجــاء فيــه مانصــه (وقبيــل القبــض‬\n     ‫علــي كنــت مبحــل حالقــه ووضــع لــي مكيــاج وصنفــرة وروج الشــفاه‬\n     ‫وكحــل للعينــن وكنــت واضع ـ ًا لعدســات الصقــه علــى عينــاي زرقــاء‬\n     ‫اللــون وتعطــرت بعطــر نســائي وقــد واعــدت أحــد زمالئــي بالدارســة‬\n     ‫لكنــه لــم يحضــر وذلــك للتســلية وأمــا مــا يختــص بالصــورة بجهــاز‬\n     ‫هاتفــي النقــال ‪ ......‬لــي شــخصي ًا حيــث مت التقاطهــا بوضــع كاميــرا‬\n     ‫اجلــوال علــى األتوماتيــك وأنــا وشــخص آخــر مــن أهل الكويــت قريب لي‬\n     ‫نتبــادل القبــات كل شــفة باألخــرى والصــور اإلباحيــة وصــورة العضــو‬\n     ‫الذكــري قمــت بتحميلهــا مــن األنترنــت ومــا يختــص ‪......‬الشــعر والشــال‬\n\n\n‫‪21‬‬\n\f‫النســائي وكــرمي األســاس فهــي عائــدة ألحــدى شــقيقاتي وتدعــى ‪.)......‬‬\n‫اه ـ كمــا جــرى االطــاع علــى محضــر القبــض املعــد مــن قبــل هيئــة ‪......‬‬\n‫لألمــر باملعــروف والنهــي عــن املنكــر لفــة رقــم ‪ 2‬مــن املعاملــة فوجدتــه‬\n‫مطابــق ملــا جــاء يف دعــوى املدعــي العــام كمــا جــرى االطــاع علــى‬\n‫محضــر املضبوطــات لفــة رقــم ‪ 16،15‬مــن املعاملــة فوجدتــه مطابــق ملــا‬\n‫جــاء يف دعــوى املدعــي العــام وبعــرض ذلــك علــى املدعــى عليــه قــال نعــم‬\n‫لقــد وقعــت علــى اإلقــرار ألن احملقــق قــال لــي وقــع فوقعــت حتــى أخــرج‬\n‫أمــا بالنســبة حملضــر هيئــة األمــر باملعــروف والنهــي عــن املنكــر فــا‬\n‫أوافــق عليــه وبالنســبة للمضبوطــات فهــي عائــدة ألهلــي هــذه إجابتــي‬\n‫ثــم جــرى مناصحــة املدعــى عليــه وبيــان عاقبــة التشــبه بالنســاء فبنــاء‬\n‫علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه بأنــه‬\n‫كان البســا عنــد القبــض عليــه بنطلونــا أســود وفانيلــة خضــراء وأنكــر‬\n‫أنــه كان مشــقرا حلواجبــه ولبســه العدســات والتعطــر بالعطــر النســائي‬\n‫وحيــث أقــر بــأن الصــورة املوجــودة يف اجلــوال عائــدة لــه وذكــر بأنــه‬\n‫يدخلهــا الدبلجــه وأنكــر علمــه بالصــور املوجــودة باجلهــاز وحيــث ذكــر‬\n‫بــأن األغــراض املوجــودة يف الســيارة عائــدة ألهلــه ولقولــه عليــه الصــاة‬\n‫والســام ( لعــن اهلل املتشــبهني مــن الرجــال بالنســاء واملتشــبهات مــن‬\n‫النســاء بالرجــال ) رواه البخــاري وحيــث إن التهمــة القويــة تتوجــه إلــى‬\n‫املدعــى عليــه بالتشــبه بالنســاء ومتكــن شــخص مــن تقبيــل الشــفاه‬\n‫ويــدان بتخزينــه لصــور بجوالــه مخلــة بــاآلداب وحكمــت علــى املدعــى‬\n‫عليــه مبــا يلــي أوال جلــد املدعــى عليــه مائــة جلــده موزعــة علــى دفعتــن‬\n‫كل دفعــة خمســن جلــده وبــن كل دفعــة وأخــرى ســبعة أيــام ثانيــا‬\n‫ســجن املدعــى عليــه ملــدة خمســة أيــام ثالث ـ ًا مصــادرة اجلــوال وبعــرض‬\n\n\n                                                                                    ‫‪22‬‬\n\f     ‫احلكــم علــى الطرفــن قــرر املدعــى عليــه القناعــة أمــا املدعــي العــام‬\n     ‫فقــرر عــدم القناعــة وطلــب رفــع احلكــم إلــى محكمــة االســتئناف‬\n     ‫مكتفيــا بالئحــة الدعــوى وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                    ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/23‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم اخلميــس املوافــق‪1434/10/08‬‬\n     ‫ه ـ افتتحــت اجللســة الســاعة العاشــرة صباحــا وحيــث عــادت املعاملــة‬\n     ‫مــن محكمــة االســتئناف بالقصيــم حســب خطــاب رئيســها رقــم‬\n     ‫‪ 341980920‬يف ‪1434/9/17‬ه ـ املتعلقــة بدعــوى املدعــي العــام ضــد‬\n     ‫‪ ......‬وبرفقــه القــرار رقــم ‪ 34312086‬يف‪1434/9/3‬ه ـ وجــاء فيــه مــا‬\n     ‫نصــه ( وبدارســة القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ أن مــا‬\n     ‫حكــم بــه فضيلتــه علــى املدعــى عليــه مــن ســجن قليــل جــدا لبشــاعة‬\n     ‫جرمــه وملخالفــة أمــر اهلل ورســوله وملضــادة الفطــرة ) وقــد حضــر يف‬\n     ‫هــذه اجللســة املدعــي العــام واملدعــى عليــه ‪ ......‬وبعــد التأمــل فقــد رجعــت‬\n     ‫عــن حكمــي الفقــرة أوال وثانيــا وحكمــت علــى املدعــى عليــه مبــا يلــي‬\n     ‫أوال ‪ :‬جلــد املدعــى عليــه ثالثمائــة جلــده موزعــة علــى ســت دفعــات كل‬\n     ‫دفعــة خمســن جلــده وبــن كل دفعــة وأخــرى ســبعة أيــام ثانيــا ‪ :‬ســجن‬\n     ‫املدعــى عليــه ملــدة عشــرين يومــا وبعــرض احلكــم علــى الطرفــن قــررا‬\n     ‫عــدم القناعــة واكتفــى املدعــي العــام بالئحــة الدعــوى أمــا املدعــى عليــه‬\n     ‫فطلــب رفــع احلكــم إلــى محكمــة االســتئناف بــدون الئحــة اعتراضيــة‬\n     ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                   ‫وســلم ‪ .‬حــرر يف ‪1434/10/8‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم الثالثــاء املوافــق ‪1434/11/18‬ه ـ‬\n     ‫الســاعة احلاديــة عشــرة وحيــث عــادت املعاملــة مــن محكمــة االســتئناف‬\n\n\n‫‪23‬‬\n\f‫بالقصيــم حســب خطــاب رئيســها رقــم ‪ 342343377‬يف ‪1434/11/5‬ه ـ‬\n‫املتعلقــة بدعــوى املدعــي العــام ضــد ‪ ......‬وبرفقــة القرار رقــم ‪34336588‬‬\n‫يف ‪1434/10/21‬ه ـ املتضمــن املصادقــة علــى احلكــم وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                              ‫‪1434/11/18‬هـ‬\n‫احلمــد هلل وحــده وبعــد‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف بـمـنـطـق ــة الـقـصـي ــم علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئي ــس احملكمــة العامــة مبحافظــة املذنــب‬\n‫الشــيخ‪ ................. /‬برق ــم (‪ )341980920‬وتاريــخ ‪1434/10/14‬ه ـ ؛‬\n‫املقيــدة لدينــا برقــم (‪ )342343377‬وتاريــخ ‪1434/10/18‬ه ـ ؛ املرفــق‬\n‫بهــا القــرار رقــم (‪ )34276758‬وتاريــخ ‪1434/7/23‬ه ـ ؛ الصــادر مــن‬\n‫فضيلتــه ؛ اخلــاص بدعــوى املدعــي العــام ضــد‪ .............../‬؛ التهامــه‬\n‫بالتشــبه بالنســاء ‪ ،‬وقــد تضمــن القــرار حكــم فضيلتــه علــى املدعــى‬\n‫عليــه بالســجن واجللــد علــى النحــو املفصــل فيــه وقــد ســبق منــا دراســة‬\n‫القــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه‬\n‫فضيلتــه واحلقــه بـ(القــرار وضبطــه) بنــاء علــى قرارنــا رقــم‪34312086‬‬\n‫وتاريــخ ‪1434/9/3‬ه ـ قررنــا املصادقــة بعــد اإلجــراء األخيــر واهلل‬\n  ‫املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n\n\n\n\n                                                                                     ‫‪24‬‬\n\f25\n\f26\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":17,"source_page_end":26,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1245d51a324584599fe77e5343abf10c19e3379821429a6e027fed8992124d25","normalized_text_hash":"8f395a4fa879ac2301286027fcbd3775f753331c083b24484010025a0d46d6d5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p17-34276758"},{"id":"b214b05b-27da-5c25-a5d4-b5021f910c5d","document_type":"judgment","category":"judicial","subcategory":"general","title":"نشوز الزوجة -دعاوى نشوز الزوجة من القضايا اخلاصة التي ال يقام ألجلها دعوى عامة -صرف النظر لعدم وجاهة الطلب .","document_number":"3436685","case_number":"3461857","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة وإمنا ذكرت ذلك يف معرض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/12","year":"1434","subject":"نشوز الزوجة -دعاوى نشوز الزوجة من القضايا اخلاصة التي ال يقام ألجلها دعوى عامة -صرف النظر لعدم وجاهة الطلب .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3436685 :‬تاريخه‪1434/2/12 :‬هـ‬\n                         ‫رقم الدعوى‪3461857 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34328396‬تاريخه‪1434/10/12 :‬هـ‬\n\n\n     ‫نشــوز الزوجــة ‪ -‬دعــاوى نشــوز الزوجــة مــن القضايــا اخلاصــة التــي ال‬\n         ‫يقــام ألجلهــا دعــوى عامــة ‪ -‬صــرف النظــر لعــدم وجاهــة الطلــب ‪.‬‬\n\n\n\n\n                                     ‫فتوى اللجنة الدائمة لإلفتاء ( ‪. )165/19‬‬\n\n\n\n\n     ‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليهــا باخلــروج مــن‬\n     ‫منــزل زوجهــا دون إذنــه وطلــب إثبــات مــا أســند إليهــا وإيقــاع العقوبــة‬\n     ‫التعزيريــة عليهــا حيــث تقــدم أحــد املواطنــن اخلليجيــن بإخباريــة بــأن‬\n     ‫زوجتــه متغيبــة عــن املنــزل وذهابهــا إلــى بيــت خالتهــا ‪ ،‬جــرى التوجــه‬\n     ‫لبيــت خالهــا وســؤاله عنهــا فأفــاد بأنهــا موجــودة لديــه باملنــزل واســتعد‬\n     ‫بإحضارهــا وقــام بتســليمها للفرقــة ثــم إلــى الشــرطة ‪ ،‬بنــاء علــى ما تقدم‬\n     ‫مــن الدعــوى ولعــدم وجاهــة رفعهــا لعــدم تعلقهــا بحــق عــام وال تخــص‬\n     ‫املصلحــة العامــة ‪ ،‬وألن الدعــوى العامــة إمنــا ترفــع حفاظــا علــى املصلحــة‬\n     ‫العامــة يف اجلرائــم املخلــة واملؤثــرة وال يتــم حتريكهــا ‪ ،‬وألن خــروج املرأة‬\n     ‫مــن بيــت زوجهــا إلــى بيــت خالهــا مســألة فقهيــة خاصــة بــن الزوجــن ‪،‬‬\n     ‫ولهــا أحكامهــا املترتبــة عليهــا مــن نشــوز ونفقــة ذكرهــا العلمــاء يف‬\n     ‫كتــب الفقــه ‪ ،‬وقــد كفــل النظــام للــزوج حفــظ حقــه باملطالبــة بــه برفــع‬\n\n‫‪27‬‬\n\f‫الدعــوى بذلــك يف احملاكــم العامــة بطلــب االنقيــاد ونحــوه لــذا كلــه‬\n‫صرفــت احملكمــة النظــر عــن طلــب املدعــي العــام لعــدم وجاهتــه ‪ ،‬قــرر‬\n‫املدعــي العــام االعتــراض علــى احلكــم بالئحــة ‪ ،‬صــدق احلكــم مــن‬\n                                                       ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة‬\n‫اجلزائيــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 3461857‬وتاريــخ‬\n‫‪ 1434/02/06‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34311202‬وتاريــخ‬\n‫‪1434/2/6‬ه ـ ففــي يــوم االثنــن املوافــق‪ 1434/02/11‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 02 : 15‬وفيهــا حضــر املدعــي العــام ……… املعمــد من‬\n‫مرجعــه باخلطــاب رقــم ‪ ...............‬وتاريــخ ‪1434/1/24‬ه ـ وادعــى علــى‬\n‫احلاضــرة معــه ‪ ...........‬مينيــة اجلنســية مبوجــب جــواز الســفر رقــم ‪...........‬‬\n‫ا يف دعــواه حيــث أنــه بتاريــخ ‪1434/1/13‬ه ـ قبــض عليهــا مــن قبــل‬          ‫قائـ ً‬\n‫ـاء علــى إخباريــة املدعــو ‪-........... /‬‬\n                                        ‫شــعبة التحريــات والبحــث اجلنائــي بنـ ً‬\n‫بحرينــي اجلنســية ‪ -‬عــن تغيــب زوجتــه املدعــي عليهــا املذكــورة وذهابهــا‬\n‫لــدى خالتهــا ‪ -‬وأنــه مــن خــال بــث التحريــات جــرى االنتقــال الــى احلــي‬\n‫املذكــور وشــوهد خالهــا املدعــو‪........... /‬بجــوار املنــزل ومبســائلته عــن‬\n‫املدعــي عليهــا ذكــر بأنهــا متواجــدة لديــه باملنــزل واســتعد بإحضارهــا‬\n    ‫وقــام بتســليمها للفرقــة ‪ -‬وجــرى تســليمها ملركــز شــرطة ‪0...........‬‬\n‫‪ -1‬بضبــط افــادة زوج املدعــي عليهــا ذكــر بــأن زوجتــه خرجــت مــن مقــر‬\n‫ســكنه بــدون إذنــه وذهبــت ملنــزل خالتهــا وال يتهــم أحــد ًا يف التســبب‬\n\n                                                                                          ‫‪28‬‬\n\f           ‫بتغيبهــا وأقــر بأنــه ال يرغــب يف اســتالمها ألنهــا خرجــت مــن شــوره‬\n     ‫‪ -2‬باســتجواب املدعــي عليهــا أقــرت بأنهــا طلبــت مــن زوجهــا أن يوصلهــا‬\n     ‫إلــى منــزل خالتهــا بســبب مشــاكل وخالفــات حدثــت بينهمــا ولكنــه‬\n     ‫رفــض وتعــذر بعــدم وجــود ســيارة لديــه فقامــت باخلــروج والذهــاب خلالتها‬\n     ‫التــي هــي يف حكــم والدتهــا بعــد وفاتهــا وهــي مــن قامــت بتربيتهــا كمــا‬\n                                   ‫أضافــت بأنهــا ال ترغــب يف العــودة إليــه مطلقـ ًا ‪.‬‬\n     ‫وانتهــى التحقيــق إلــى توجيــه االتهــام للمدعــي عليهــا‪ ،........... /‬باخلــروج‬\n                                                            ‫مــن منــزل زوجهــا دون إذنــه ‪.‬‬\n                                                          ‫وذلك لألدلة والقرائن التالية‪:‬‬\n     ‫‪ -1‬إقرارهــا املنــوه عنــه واملــدون مبلــف االســتجواب الثانــي املرفــق باللفــة‬\n                                                                                ‫رقــم (‪.)26‬‬\n     ‫‪ -2‬شــهادة الشــهود املدونــة مبحضــر القبــض املنــوه عنــه واملرفــق باللفــة‬\n                                                                               ‫رقــم (‪. )17‬‬\n     ‫وحيــث أن مــا أقدمــت عليــه املدعــي عليهــا املذكــورة فعــل محــرم‬\n     ‫ومعاقــب عليــه شــرع ًا اطلــب إثبــات مــا اســند إليهــا واحلكــم عليهــا‬\n     ‫بعقوبــة تعزيريــة ( علمـ ًا بــأن احلــق اخلــاص ال زال قائمـ ًا ) فبنــاء علــى مــا‬\n     ‫تقــدم مــن الدعــوى ولعــدم وجاهــة رفعهــا وعــدم تعلقهــا بحــق عــام وال‬\n     ‫تخــص املصلحــة العامــة وألن الدعــوى العامــة إمنــا ترفــع حفاظــا علــى‬\n     ‫املصلحــة العامــة يف اجلرائــم املخلــة واملؤثــرة وال يتــم حتريكهــا ورفعهــا‬\n     ‫يف الشــؤون اخلاصــة مثــل هــذه الدعــوى وألن مســالة خــروج املــرأة مــن‬\n     ‫بيــت زوجهــا إلــى بيــت خالهــا مســالة فقهيــة خاصــة بــن الزوجــن ولهــا‬\n     ‫احكامهــا املترتبــة عليهــا مــن نشــوز ونفقــة ذكرهــا العلمــاء يف مظانهــا‬\n     ‫وخروجهــا ألهلهــا أصــا محــل خــاف بــن اهــل العلــم يف اشــترط‬\n\n\n‫‪29‬‬\n\f‫إذن زوجهــا مــن عدمــه وقــد أجابــت اللجنــة الدائمــة لإلفتــاء عــن ذلــك‬\n‫وأجــازت خــروج الزوجــة دون إذن زوجهــا إذا كان هنــاك مســوغ شــرعي‬\n‫انظــر فتــاوى اللجنــة الدائمــة ‪19/165‬وقــد كفــل النظــام للــزوج حفــظ‬\n‫حقــه واملطالبــة بــه برفــع الدعــوى بذلــك يف احملاكــم العامــة بطلــب‬\n‫االنقيــاد ونحــوه لــذا كلــه فقــد صرفــت النظــر عــن طلــب املدعــي العــام‬\n‫لعــدم وجاهتــه وبعرضــه عليــه قــرر االعتــراض بالئحــة وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                               ‫‪1434/2/11‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ثــم عــادت إلينــا أوراق املعاملــة مــن محكمــة‬\n‫االســتئناف وبرفقهــا القــرار رقــم ‪ 34241106‬وتاريــخ ‪1434/6/14‬ه ـ‬\n‫املتضمــن أنــه بدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫تقــرر باألكثريــة إعادتهــا لفضيلــة حاكمهــا ملالحظــة أن القضيــة مــن‬\n‫اختصــاص ناظرهــا وليــس مــن اختصــاص احملاكــم العامــة لكــون‬\n‫مــا أقدمــت عليــه املدعــى عليهــا فعــل يســتوجب العقــاب عليــه خلروجهــا‬\n‫بــدون علــم زوجهــا وإذنــه وتغيبهــا عــن ســكن زوجهــا بيــت الطاعــة ممــا‬\n‫دفعــه إلــى اإلخبــار عنهــا وهــذه معصيــة أقدمــت عليهــا يعــاد النظــر واهلل‬\n‫املوفــق‪ ،‬وعليــه أجيــب أصحــاب الفضيلــة مشــايخي الكــرام وفقنــي‬\n‫اهلل وإياهــم لــكل خيــر بأننــي لــم أدفــع بــأن الدعــوى مــن اختصــاص‬\n‫احملكمــة العامــة وإمنــا ذكــرت ذلــك يف معــرض حيثياتــي التــي صــرف‬\n‫بهــا النظــر عــن الدعــوى وأعنــي بذلــك أن الدعــوى العامــة كمــا ال‬\n‫يخفاكــم ترفــع يف املصالــح العامــة ومــا يخــل بهــا وقضايــا العــن اخلاصــة‬\n‫ال تنشــأ مــن أجلهــا وحتــرك الدعــاوى ومــا يحصــل بــن الزوجــن مــن‬\n‫خالفــات أســرية يعتبــر مــن القضايــا اخلاصــة ال ســيما إذا علمنــا أنهــا‬\n\n\n                                                                                    ‫‪30‬‬\n\f     ‫خرجــت لبيــت أهلهــا كمــا هــو محــرر يف أصــل الدعــوى وعليــه ‪-‬والنظــر‬\n     ‫لكــم أصحــاب الفضيلــة ‪ -‬لــم يظهــر لــي ســوى مــا ســبق تقريــره وأمــرت‬\n     ‫بإحلــاق ذلــك بالضبــط والقــرار ومــن ثــم بعثــه ألصحــاب الفضيلــة حســب‬\n     ‫املتبــع وبــاهلل تعالــى التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                        ‫وصحبــه وســلم حــرر يف ‪1434/08/03‬ه ـ‬\n     ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪ ...‬نحــن رئيــس‬\n     ‫وقضــاة الدائــرة اجلزائيــة الرابعــة يف محكمــة االســتئناف مبنطقــة‬\n     ‫مكــة املكرمــة جــرى منــا االطــاع علــى القــرار رقــم ‪3436685‬‬\n     ‫وتاريــخ ‪1434/2/12‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ ............. /‬القاضــي‬\n     ‫باحملكمــة اجلزائيــة مبكــة املكرمــة ‪ ،‬املتضمــن دعــوى املدعــي العــام‬\n     ‫ضــد‪ ........... /‬مينيــة اجلنســية ‪ ،‬املتهمــة باخلــروج مــن منــزل زوجهــا دون‬\n     ‫إذنــه ‪ ،‬احملكــوم فيــه مبــا دون باطنــه املالحــظ عليــه بقــرار محكمــة‬\n     ‫االســتئناف رقــم ‪ 34241106‬وتاريــخ ‪1434/6/14‬هـ ـ ‪ .‬وبدراســة القــرار‬\n     ‫وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة علــى احلكــم‬\n     ‫بعــد اجلــواب األخيــر‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                               ‫آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪31‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":27,"source_page_end":31,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a461319d984fcec5d6d6caac75e482fb5e8bc78e7afc7324a19fdbf4c8c5b0cf","normalized_text_hash":"8eaecbaeecf7e36dda7737e1b18d94285f3f66389750f35000802a30ff41ae97","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p27-3436685"},{"id":"952fb135-cb23-5a7c-8f14-46864036a214","document_type":"judgment","category":"judicial","subcategory":"general","title":"اشتراك بإفساد وتخبيب زوجة على زوجها -حتريض زوجة على الهروب مع أوالدها القصر -تدخل يف خصوصية حياة زوجية - دفع موضوعي غير مقبول -تخبيب املرأة على زوجها من كبائر الذنوب -أدلة الشريعة يف حترمي تخبيب املرأة على زوجها -تشديد العقوبة -توجيه تهمة -إثبات إدانة -تعزير -سجن للحق العام واخلاص -منع من السفر للحق العام .","document_number":"342288858","case_number":"33525902","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية على املعاملة املقيدة لدى المحكمة ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/6","year":"1434","subject":"اشتراك بإفساد وتخبيب زوجة على زوجها -حتريض زوجة على الهروب مع أوالدها القصر -تدخل يف خصوصية حياة زوجية - دفع موضوعي غير مقبول -تخبيب املرأة على زوجها من كبائر الذنوب -أدلة الشريعة يف حترمي تخبيب املرأة على زوجها -تشديد العقوبة -توجيه تهمة -إثبات إدانة -تعزير -سجن للحق العام واخلاص -منع من السفر للحق العام .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 342288858 :‬تاريخه‪1434/8/6 :‬هـ‬\n                   ‫رقم الدعوى‪33525902 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34341845‬تاريخه‪1434/10/27 :‬هـ‬\n\n\n‫اشــتراك بإفســاد وتخبيــب زوجــة علــى زوجهــا ‪ -‬حتريــض زوجــة علــى‬\n‫الهــروب مــع أوالدهــا القصــر ‪ -‬تدخــل يف خصوصيــة حيــاة زوجيــة ‪-‬‬\n‫دفــع موضوعــي غيــر مقبــول ‪ -‬تخبيــب املــرأة علــى زوجهــا مــن كبائــر‬\n‫الذنــوب ‪ -‬أدلــة الشــريعة يف حتــرمي تخبيــب املــرأة علــى زوجهــا ‪ -‬تشــديد‬\n‫العقوبــة ‪ -‬توجيــه تهمــة ‪ -‬إثبــات إدانــة ‪ -‬تعزيــر ‪ -‬ســجن للحــق العــام‬\n                               ‫واخلــاص ‪ -‬منــع مــن الســفر للحــق العــام ‪.‬‬\n\n\n\n\n‫‪ -‬قــال صلــى اهلل عليــه وســلم‪( :‬ليــس منــا مــن خبــب امــرأة علــى زوجهــا‬\n                                                       ‫أو عبــدا علــى ســيده)‪.‬‬\n‫‪ -‬قــال صلــى اهلل عليــه وســلم‪( :‬مــن خبــب زوجــة امــرئ أو مملوكــة‬\n‫فليــس منــا) رواه أبــو داود ‪ ،‬قــال يف عــون املعبود‪« :‬أي خدعها وأفســدها»‪.‬‬\n‫‪ -‬قــال يف االقنــاع ((وقــال ‪ -‬أي شــيخ اإلســام ‪ -‬يف رجــل خبــب امــرأة‬\n‫علــى زوجهــا يعاقــب عقوبــة بليغــة)) ينظــر‪ :‬كشــاف القنــاع عــن مــن‬\n                                                            ‫االقنــاع (‪.)68/4‬‬\n\n\n\n\n‫انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليهمــا (امرأتــان)‬\n‫باالشــتراك بإفســاد وتخبيــب زوجــة (غيــر ســعودية) علــى زوجهــا‬\n\n                                                                                  ‫‪32‬‬\n\f     ‫وحتريضهــا علــى الهــرب بأبنائهــا الســعوديني القصــر وعــدم جتاوبهمــا‬\n     ‫مــع جهــة التحقيــق عنــد طلبهمــا وعــدم جتاوبهمــا أثنــاء االســتجواب‬\n     ‫وذلــك إثــر ورود بــاغ للجهــات املختصــة مــن أحــد املواطنــن مفــاده‬\n     ‫اتصــال امرأتــن علــى زوجتــه ؛ حملاولــة خطفهــا وتهريبهــا ‪ ،‬بالبحــث‬\n     ‫لــم يعثــر لهــن علــى ســوابق ‪ ،‬طلــب املدعــي العــام إثبــات مــا أســند إليهمــا‬\n     ‫واحلكــم عليهمــا بعقوبــة تعزيريــة ‪ ،‬بعــرض دعــوى املدعــي العــام علــى‬\n     ‫املدعــى عليهــا األولــى أنكرتهــا‪ ،‬ودفعــت أن والــدة زوجــة املدعــي يف‬\n     ‫احلــق اخلــاص اتصلــت بهــا قبــل ســنتني تطلــب مســاعدتها كــون ابنتهــا‬\n     ‫تعانــي مــن قلــة الطعــام والشــراب ‪ ،‬وأنهــا قدمــت مــع املدعــى عليهــا‬\n     ‫الثانيــة ملســاعدتها‪ ،‬وصادقــت علــى عــدم التجــاوب أثنــاء االســتجواب‬\n     ‫فهــذا ألنهــا ال تعــرف مــا هــي التهمــة املوجهــة لهــا‪ ،‬وبعــرض الدعــوى‬\n     ‫علــى املدعــى عليهــا الثانيــة أنكرتهــا ودفعــت أن املدعــى عليهــا األولــى‬\n     ‫أخبرتهــا أن زوجــة املدعــي يف احلــق اخلــاص تعانــي مــن ضيــق العيــش‬\n     ‫وتطلــب املســاعدة يف تأمــن الطعــام والشــراب فاتصلـ ُـت بهيئــة حقــوق‬\n     ‫اإلنســان وأخبرتهــم باملوضــوع وعاجلــوا املشــكلة‪ ،‬وقبــل القبــض عليهــا‬\n     ‫بيــوم أخبرتهــا املدعــى عليهــا األولــى أن املــرأة املذكــورة قــد ســافر عنهــا‬\n     ‫زوجهــا ملــدة خمســة أيــام وأقفــل بــاب الشــقة عليهــم وال يوجــد طعــام لهــا‬\n     ‫وألطفالهــا فذهبــت هــي واملدعــى عليهــا األولــى مــع ســائقها للمــرأة‬\n     ‫لكــي يأخذانهــا ويشــتريان حاجياتهــا‪ ،‬وصادقــت علــى عــدم التجــاوب‬\n     ‫أثنــاء االســتجواب ألنهــا ال تعــرف التهمــة املوجهــة لهــا ‪ ،‬حضــر املدعــي‬\n     ‫باحلــق اخلــاص وادعــى علــى املدعــى عليهمــا أنهمــا حضرتــا لكــي‬\n     ‫يأخــذن زوجتــه وأطفالــه وتذهبــان بهمــا إلــى الســفارة ‪ ....‬بالريــاض‬\n     ‫وطلــب تعزيــر املدعــى عليهمــا لقــاء محاولتهمــا تهريــب زوجتــه وأطفالــه‬\n\n\n‫‪33‬‬\n\f‫إلــى جهــة خارجيــة وتخبيبهمــا زوجتــه عليــه‪ -‬بعــرض دعــوى املدعــي يف‬\n‫احلــق اخلــاص علــى املدعــى عليهمــا قررتــا أن جوابهمــا هــو نفــس اجلــواب‬\n‫علــى الدعــوى يف احلــق العــام ‪ ،‬جــرى االطــاع علــى محضــر تنفيــذ املهمــة‬\n‫‪ ،‬جــرى االطــاع علــى ضبــط إفــادة زوجــة املدعــي اخلــاص ‪ ،‬ألن املدعــى‬\n‫عليهمــا أقرتــا بقيامهمــا بتســليم زوجــة املدعــي اخلــاص جهــاز جــوال‬\n‫بشــريحة ومبلــغ مالــي ســر ًا قبــل ســنة مــن القبــض عليهمــا وقــد حفظــا‬\n‫يف هــذا اجلهــاز املقــدم رقمــي جوالهمــا وألن املدعــى عليهمــا أقرتــا أنهمــا‬\n‫حضرتــا إلــى منــزل املدعــي اخلــاص وذلــك ألجــل أخــذ زوجتــه وأطفالــه‬\n‫معهمــا وقــد أقرتــا بأنهمــا قــد طلبتــا مــن املــرأة جتهيــز شــنطة للطفــل‬\n‫الرضيــع كــي تخــرج املــرأة وأطفالهــا وتركــب معهمــا يف الســيارة وال‬\n‫شــك أن تواصــل املدعــى عليهمــا مــع املــرأة وطلبهمــا هــذا الطلــب منهــا‬\n‫دون علــم زوجهــا هــو ســعي إلفســاد املــرأة علــى زوجهــا وتخبيــب لهــا‬\n‫كمــا أنــه يوجــه التهمــة للمدعــى عليهمــا بتحريــض املــرأة علــى الهــرب‬\n‫بأطفالهــا وهــذا تخبيــب للمــرأة وتهمــة يف حتريضهــا علــى الهــرب مــع‬\n‫أطفالهــا والقبــول مبــا دفعــت بــه املدعــى عليهمــا يفتــح باب ـ ًا للفوضــى‬\n‫والشــر وجتــاوز النظــام وحيــث إن تخبيــب املــرأة علــى زوجهــا مــن كبائــر‬\n‫الذنــوب وألنــه ال بينــة علــى عــدم جتــاوب املدعــى عليهمــا عنــد طلبهمــا‬\n‫فاحملضريــن املدونــن مــن قبــل احملقــق يــدالن علــى حضــور املدعــى‬\n‫عليهمــا عنــد طلبهمــا وأمــا عــدم إجابتهمــا علــى أســئلة احملقــق فهــذا يعــد‬\n‫نكــو ًال علــى اجلــواب وال مســتند يف التعزيــر عليــه لــذا ثبــت قيــام املدعــى‬\n‫عليهمــا مبحاولــة تخبيــب املــرأة علــى زوجهــا املدعــي اخلــاص كمــا‬\n‫توجهــت التهمــة للمدعــى عليهمــا بتحريــض املــرأة زوجــة املدعــي اخلــاص‬\n‫علــى الهــرب بأطفالهمــا وقــررت تعزيــر املدعــى عليهمــا لقــاء مــا تقــدم‬\n\n\n                                                                                       ‫‪34‬‬\n\f     ‫بســجن كل واحــدة منهمــا مــدة عشــرة أشــهر خمســة أشــهر منهــا للحــق‬\n     ‫العــام وخمســة أشــهر للحــق اخلــاص ومنــع املدعــى عليهمــا مــن الســفر‬\n     ‫خــارج اململكــة مــدة ســنتني بعــد تنفيــذ محكوميتهمــا واملنــع من الســفر‬\n     ‫للحــق العــام ولــم يثبــت حتريــض املدعــى عليهمــا للمــرأة زوجــة املدعــي‬\n     ‫اخلــاص علــى الهــرب بأطفالهمــا كمــا لــم يثبــت لــدي أن املدعــى عليهمــا‬\n     ‫لــم يتجاوبــا مــع جهــة التحقيــق عنــد طلبهمــا وعــدم اســتحقاق املدعــى‬\n     ‫عليهمــا للتعزيــر علــى عــدم جتاوبهمــا أثنــاء اســتجوابهما ومت احلكــم‬\n     ‫بذلــك كلــه ‪ ،‬بعــرض احلكــم علــى املدعــى عليهمــا لــم تقنعــا‪ ،‬وبعــد‬\n                     ‫رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n     ‫‪........‬القاضــي باحملكمــة اجلزائيــة باخلبــر وبنــاء علــى املعاملــة احملالــة‬\n     ‫لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة يف محافظــة اخلبــر برقــم‬\n     ‫‪ 33525902‬وتاريــخ ‪ 1433/08/14‬ه ـ املقيــدة باحملكمــة برقــم‬\n     ‫‪ 331536782‬وتاريــخ ‪ 1433/08/14‬ه ـ ففــي يــوم األربعــاء‬\n     ‫املوافــق‪ 1433/10/25‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 00‬وفيهــا قــدم‬\n     ‫املدعــي العــام‪ ........‬الئحــة دعــوى عامــة ضــد [‪ ........ ]1‬ســعودية اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم (‪ ........ ]2[ )........‬ســعودية اجلنســية مبوجــب‬\n     ‫ا فيهــا حيــث أنــه باالطــاع علــى‬        ‫الســجل املدنــي رقــم (‪ )........‬قائ ـ ً‬\n     ‫محضــر تنفيــذ مهمــة املعــد مــن قبــل رجــال الدوريــة األمنيــة تبــن انــه‬\n     ‫عنــد الســاعة ‪6:35‬م مــن يــوم األحــد املوافــق ‪1432/7/4‬ه ـ ورد بــاغ‬\n     ‫لغرفــة العمليــات مــن املواطــن ‪ ........‬مفــاده حضــور امرأتــن واتصالهمــا‬\n\n‫‪35‬‬\n\f‫علــى زوجتــه ومحاولــة تهريبهــا وخطفهــا وبانتقــال الدوريــة للموقــع بحــي‬\n‫‪........‬بالدمــام واالنتظــار مت مشــاهدة الزوجــة وأطفالهــا والعفــش معهــم‬\n‫ينزلــون الــى املرأتــن بعدهــا تدخــل الــزوج وارجــع زوجتــه وأطفالــه للشــقة‬\n‫وأفــاد بــان العناصــر املوجــودة حتــاول خطــف زوجتــه وتهريــب أطفالــه‬\n‫معهــا وقامــت (‪ )........‬برفــع صوتهــا عليــه وبضبــط إفــادة املدعــي ‪........ /‬‬\n‫أفــاد انــه تــزوج ‪ .... (........‬اجلنســية) منــذ ‪10‬ســنوات وأجنــب منهــا ثالثــة‬\n‫أطفــال ‪........‬عمــره (‪9‬ســنوات) و‪ ........‬عمره(‪5‬ســنوات) و ‪........‬عمرهــا‬\n‫(ســنتني وأربعــة أشــهر) وان والــدة زوجتــه زارتهــم قبــل عشــر ســنوات ولــم‬\n‫يعجبهــا وضعهــم املــادي وتفاجــأ قبــل شــهرين أن (‪ )........‬نســقت مــع‬\n‫زوجتــه ملقابلــة (‪ )........‬يف مجمــع ‪........‬وقابلتهــا يف دورة امليــاه وأعطــت‬\n‫زوجتــه جهــاز جــوال ومبلــغ ‪300‬ريــال ولــم يعــرف بهــذا اللقــاء إال بعــد‬\n‫بالغــه علــى املتهمتــن ‪ ،‬حيــث أنــه بتاريــخ ‪1432/7/4‬ه ـ خرج من شــقته‬\n‫يف فتــرة العصــر ملمارســة الرياضــة فاتصلــت عليــه زوجتــه ‪........‬وأخبرتــه‬\n‫أن (‪........‬و ‪ )........‬قادمتــن إليهــا يف الطريــق وســوف يأخذونهــا وأبنائهــا‬\n‫إلــى الســفارة ‪ .....‬بالريــاض وطلبــوا منهــا جتهيــز شــنطتها فاخبــر زوجتــه‬\n‫بأنــه عائــد للمنــزل وابلــغ الدوريــات بذلــك وبعــد املغــرب ورد اتصــال‬\n‫جلــوال زوجتــه مــن ‪........‬وطلبــت منهــا اخلــروج مع أبنائها والشــنط وكانت‬\n‫الدوريــة متواجــدة يف املــكان وقامــوا بــإركاب الشــنط يف ســيارتهم‬\n‫التابعــة للســائق اخلــاص ل‪ ........‬فقبضــت عليهــم الدوريــة وارجــع زوجتــه‬\n‫وأبنائــه والشــنط للشــقة وذهــب ملركز شــرطة ‪........‬وحــرر بالغ ضدهما‬\n‫بشــأن أخــذ زوجتــه وأبنائــه للســفارة ‪ ......‬بالريــاض لترحيلهــم إلــى خــارج‬\n‫البــاد وبضبــط إفــادة الزوجــة املقيمــة ‪ ..... ،........‬اجلنســية ‪ ،‬أفــادت انــه‬\n‫قبــل ســنة طلبــت (‪ )........‬مــن زميلتهــا (‪ )........‬مقابلتهــا يف مجمــع ‪........‬‬\n\n\n                                                                                        ‫‪36‬‬\n\f     ‫وقابلتها يف دورة املياه وســلمتها (‪ )........‬جهاز جوال مشــحون بـ‪300‬ريال‬\n     ‫ومبلــغ ‪300‬ريــال وأصبحــت (‪ )........‬تتواصــل معهــا عــن طريــق اجلــوال ولــم‬\n     ‫يســبق أن قابلتهــا إال عنــد القبــض عليهــا مــن قبــل الشــرطة ‪ ،‬وأفــادت‬\n     ‫أنهــا ال حتفــظ رقــم شــريحة اجلــوال الــذي ســلمته لهــا (‪ )........‬كونــه‬\n     ‫عندمــا حصلــت املشــكلة رمــت الشــريحة وأنكــرت أنهــا ذكــرت‬\n     ‫ل‪ ........‬أو ‪........‬أنهــا جوعانــة أو محتجــزة أو أن زوجهــا ســافر عنهــا أو‬\n     ‫طلبــت منهمــا أخذهــا للســوبر ماركــت كمــا أفــادت الزوجــة انــه بتاريخ‬\n     ‫‪1432/7/4‬ه ـ يف فتــرة العصــر أرســلت لهــا ‪........‬ثــاث رســائل (هــل أنــت‬\n     ‫لوحــدك يف املنــزل) ولــم تــرد عليهــا ثــم أرســلت ‪........‬رســالة ذكــرت‬\n     ‫(انهــا ســتحضر إلــى منزلهــا ألخذها للســفارة …‪ .‬يف الرياض) والرســالة‬\n     ‫الثالثــة (أنهــا ســوف حتضــر وتأخذهــا وعليهــا جتهيــز نفســها ) ولــم تــرد‬\n     ‫علــى الرســائل واتصلــت علــى زوجهــا وأخبرتــه بذلــك وحضــر ثــم اتصلت‬\n     ‫‪........‬وأخبرتهــا أنهــا مــع ‪........‬عنــد املنــزل وطلبــت منهــا النــزول مــع‬\n     ‫أطفالهــا والشــنط ألخذهــا للســفارة ‪ ....‬وأخبــرت زوجهــا بذلــك وأفــادت‬\n     ‫انهــا أطلعــت الشــرطة علــى الرســائل املرســلة إليهــا باللغــة االجنليزيــة‬\n     ‫بعدهــا رمــت الشــريحة وتعتقــد ان والدتهــا هــي مــن قــام بوصــف مــكان‬\n     ‫شــقتها ل‪ ........‬وأفــادت أنهــا تعيــش مــع أطفالهــا وليــس لديهــا مشــاكل‬\n     ‫وهــي مســلمة وترغــب باالســتمرار بالعيــش مــع زوجهــا وأطفالهــا عنــد‬\n     ‫طلــب املدعــى عليهمــا كانتــا متاطــان باحلضــور جلهــة التحقيــق وعــدم‬\n     ‫التجــاوب أثنــاء االســتجواب ومت حتريــر محضــر بذلــك وبســماع األقــوال‬\n     ‫األوليــة للمدعــى عليهــا ‪ ، ........ /‬أفــادت أنهــا كانــت برفقــة زميلتهــا‬\n     ‫(‪ )........‬ذاهبتــن ملســاعدة امــرأة محبوســة يف منزلهــا وأنهــا ممنوعــة مــن‬\n     ‫الطعــام وذلــك بصفتهــا إنســانه وإلحلــاح والــدة املــرأة عليهــا والتــي بحثــت‬\n\n\n‫‪37‬‬\n\f‫عــن اســمها يف مواقــع االنترنــت فتواصلــت مــع والدتهــا بعدهــا أعطتهــا‬\n‫األم …‪ ..‬رقــم جــوال ابنتهــا وتواصلــت معهــا عبــر الرســائل كونهــا ال‬\n‫تســتطيع اســتخدام اجلــوال خوفــا مــن زوجهــا وان األم كانــت تطلــب‬\n‫منهــا محاولــة تهريــب ابنتهــا مــن البلــد إلــى …‪ .‬فأخبرتهــا أن ذلــك‬\n‫مســتحيل وأفــادت انــه بينهــا وبــن املــرأة احملبوســة عــدة مســجات تطلــب‬\n‫منهــا احلضــور حــاال فحضــرت للجلــوس معهــا ومعرفــة مــا تريــد وأفــادت‬\n‫انــه تواصلــت معهــا منــذ ســنة ولــم تقابلهــا وأنهــا عضــوه يف منظمــة حقــوق‬\n‫اإلنســان يف الشــرق األوســط وليــس لديهــا مــا يثبــت ذلــك وباســتجواب‬\n‫املدعــى عليهــا ‪ ........ /‬رفضــت التجــاوب أثنــاء االســتجواب وبســماع‬\n‫األقــوال األوليــة للمدعــى عليهــا ‪ ........ /‬أفــادت أنــه قبــض عليهــا لذهابها‬\n‫لســيدة ‪ ....‬أرســلت لهــا رســالة تخبرهــا أنهــا جوعانــة وظمآنــة هــي‬\n‫وأبنائهــا وحضــرت لتزويدهــا بالطعــام وحضــرت ملنزلهــا كــي تعــرف مــا‬\n‫تريــد كــي توفــره لهــا وأفــادت أنهــا تتواصــل مــع املــرأة منــذ ســنة تقريبــا‬\n‫وتعرفــت عليهــا ‪ ........‬وتواصلــت معهــا وتعرفــت املــرأة عليهــا عــن طريــق‬\n‫‪........‬وأن والــدة املــرأة تراســلهم وتطلــب منهمــا مســاعدة ابنتهــا وأفــادت‬\n‫أنهــا طلبــت مــن زوجــة املدعــي جتهيــز شــنطة صغيــرة لــأوالد وســألتها‬\n‫عــن نــوع املســاعدة التــي تريدهــا فقالــت تريد اخلروج مــن املنزل والذهاب‬\n‫للســوبر ماركــت وكانــت معهــا ‪........‬وأفــادت أنهــا قابلــت املــرأة بنــاء‬\n‫طلــب والداتهــا كــي تعطيهــا مبلــغ مالــي كونهــا ناشــطة حقوقيــة‬\n‫وباســتجواب املدعــى عليهــا ‪........ /‬أفــادت ان املقيمــة (‪...... ،........‬‬\n‫اجلنســية) ترســل رســائل لهــا ولــ‪ ........‬مضمونها انها جائعــة هي وأطفالها‬\n‫وال يتوفــر مــاء صحــي للشــرب وترجــو املســاعدة وأفــادت انــه بتاريــخ‬\n‫‪1432/7/4‬ه ـ حضــرت إلــى املقيمــة (‪ )........‬ملســاعدتها بتوفيــر املــأكل‬\n\n\n                                                                                        ‫‪38‬‬\n\f     ‫واملشــرب وانهمــا تريدنــا ســؤالها عــن نــوع املســاعدة التــي تريدهــا‬\n     ‫والذهــاب بهــا إلــى الســوبر ماركــت لشــراء حاجياتها وعنــد حضورهما‬\n     ‫هجــم عليهمــا زوج ‪ ........‬وأخــذ أطفالــه واركبهــا وزميلتهــا الدوريــة ولــم‬\n     ‫يكــن مــع زوجــة املدعــي شــنط وأفــادت أنهــا قابلــت ‪........‬مــرة واحــدة‬\n     ‫قبــل ســنة مــن تاريــخ القبــض يف مجمــع ‪........‬وســلمتها جهــاز جــوال ومبلــغ‬\n     ‫‪500‬ريــال داخــل دورة امليــاه وأفــادت ان ‪........‬لهــا عالقــة مــع والــدة ‪........‬‬\n     ‫وان ‪........‬هــي مــن دلتهــم علــى مــكان املنــزل وأفــادت انهــا طلبــت مــن‬\n     ‫‪........‬جتهيــز شــنطة صغيــرة فيهــا حليــب وغيــار كــون معهــا طفــل رضيــع‬\n     ‫(مت إمهــال ‪........‬مــدة إلحضــار الرســائل املرســلة جلهــة التحقيــق إلثباتهــا‬\n     ‫ولــم حتضــر مــا يثبــت ذلــك حتــى حينــه) وانتهــى التحقيــق إلــى توجيــه‬\n     ‫االتهــام ل ـ ‪........‬و ‪........‬باالشــتراك بإفســاد وتخبيــب الزوجــة علــى زوجهــا‬\n     ‫وحتريضهــا علــى الهــروب بأبنائهــا الســعوديني القصــر وعــدم جتاوبهمــا‬\n     ‫مــع جهــة التحقيــق عنــد طلبهمــا وعــدم جتاوبهمــا أثنــاء االســتجواب‬\n     ‫وذلــك لألدلــة والقرائــن التاليــة‪ -1 :‬محضــر تنفيــذ مهمــة املعــد مــن قبــل‬\n     ‫رجــال الدوريــة األمنيــة املتضمــن القبــض علــى املذكورتــن عنــد منــزل‬\n     ‫املدعــي املنــوه عنــه واملرفــق لفــة رقــم (‪ -2 ) 14‬وجــود عفــش مــع الزوجــة‬\n     ‫وأطفالهــا عنــد حضــور املدعــى عليهمــا قرينــة علــى محاولــة تهريبهــا ‪-3‬‬\n     ‫مــا ورد يف أقــوال املدعــى عليهــا ‪........‬املنــوه عنــه واملــدون علــى الصفحــة‬\n     ‫رقــم ( ‪ 13‬ـ ‪ ) 15‬مــن دفتــر التحقيــق املرفــق لفــة رقــم ‪ 13‬ومــا دون علــى‬\n     ‫اللفــة رقــم ( ‪ 52‬ـ ‪ -4 ) 54‬مــا ورد يف أقــوال املدعــى عليهــا ‪........‬املنــوه‬\n     ‫عنــه واملــدون علــى الصفحــة رقــم (‪ )16‬مــن دفتــر التحقيــق مرفــق لفــة‬\n     ‫رقــم ‪ 13‬ومــا دون علــى الصفحــة رقــم ( ‪10‬ـ ‪ ) 12‬مــن دفتــر التحقيــق‬\n     ‫املرفــق لفــة رقــم ‪ 12‬ومــا دون علــى اللفــة رقــم (‪ 46‬ـ ‪ -5 ) 51‬احملضــر‬\n\n\n‫‪39‬‬\n\f‫املعــد بشــأن عــدم جتاوبهمــا لــدى جهــة التحقيــق أثنــاء االســتجواب أو‬\n‫احلضــور املنــوه عنــه واملرفــق لفــة رقــم ( ‪ )65 ، 57‬وبالبحــث عمــا إذا‬\n‫كان لهــن ســوابق لــم يعثــر لهــن علــى ســوابق مســجلة وحيــث إن مــا‬\n‫أقدمــت عليــه املدعــى عليهمــا ـ وهمــا بكامــل أهليتهمــا املعتبــرة شــرعاًـ‬\n‫فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات ما أســند إليهما واحلكم‬\n‫عليهمــا بعقوبــة تعزيريــة تزجرهمــا وتــردع غيرهمــا (احلــق اخلــاص اليــزال‬\n‫قائم ـاً) هــذه دعــواي وبســؤال املدعــى عليهمــا عــن الدعــوى أجابــت‬\n‫املدعــى عليهــا بقولهــا مــا جــاء يف الدعــوى العامــة مــن اشــتراكي مــع‬\n‫‪ ........‬بإفســاد وتخبيــب املــرأة ‪........‬علــى زوجهــا وحتريضهــا علــى الهروب‬\n‫بأبنائهــا الســعوديني القصــر هــذا غيــر صحيــح والصحيــح أنــه قبــل‬\n‫ســنتني تقريب ـ ًا مــن القبــض علينــا اتصلــت بــي والــدة املــرأة ‪........‬مــن ‪....‬‬\n‫تطلــب مســاعدتي كونــي عضــوه يف منظمــة مراقبــة حقــوق اإلنســان‬\n‫وتذكــر أن ابنتهــا ‪........‬متزوجــة مــن شــخص ســعودي وتقيــم يف الدمــام‬\n‫وتعانــي مــن قلــة الطعــام والشــراب فأخبرتهــا بــأن تفهــم ابنتهــا مبراجعــة‬\n‫هيئــة حقــوق اإلنســان بالســعودية ويبــدو أنهــا قامــت مبراجعتهــم وحتســن‬\n‫وضعهــا ثــم بعــد ســنه تقريبـ ًا مــن هــذا االتصــال أرســلت لــي املــرأة ‪........‬‬\n‫رســالة علــى جوالــي تخبرنــي بأنهــا جائعــة وتطلــب املســاعدة فقمــت‬\n‫مبراســلة صديقاتــي عــن حالتهــا ملعرفــة مــن تســتطيع مســاعدتها‬\n‫وهكــذا كانــت تأتــي رســائل علــى جوالــي بــن الفتــرة واألخــرى مــن‬\n‫هــذه املــرأة ‪........‬تشــكو مــن ســوء وضعهــا وكنــت أرســل لصديقاتــي‬\n‫هــذه الرســائل التــي تأتــي كــي يتــم مســاعدة املــرأة ‪........‬وقبــل القبــض‬\n‫علينــا بيــوم أرســلت لــي املــرأة ‪........‬رســالة نصيــه علــى جوالــي تخبرنــي‬\n‫بــأن زوجهــا مســافر ملــدة خمســة أيــام وأنهــا جائعــة هــي وأطفالهــا وقــد‬\n\n\n                                                                                          ‫‪40‬‬\n\f     ‫قــام زوجهــا بإقفــال بــاب الشــقة عليهــم وتطلــب منــي املســاعدة فأرســلت‬\n     ‫لهــا بأنــه ال ميكــن إحضــار الطعــام لهــا وزوجهــا قــد أقفــل عليهــم بــاب‬\n     ‫الشــقة فأرســلت لــي تخبرنــي بــأن لديهــا مفتــاح ســري لبــاب الشــقة ويف‬\n     ‫يــوم القبــض علينــا قمــت بالتواصــل مــع ‪........‬ألجــل مســاعدة هــذه املــرأة‬\n     ‫وذهبــت إلــى منــزل ‪........‬وركبــت معهــا علــى الســيارة التــي يقودهــا‬\n     ‫ســائقها واتصلــت باملــرأة ‪........‬ملعرفــة مــكان ســكنها كــي تركــب‬\n     ‫معنــا هــي وأطفالهــا ونذهــب إلــى الســوق لشــراء حاجياتها وعنــد وصولنا‬\n     ‫إلــى العمــارة التــي تســكن بهــا املــرأة ‪........‬يف الدمــام حــي ‪........‬وقبــل‬\n     ‫توقــف الســيارة التــي نركبهــا توقــف تــام حضــرت الدوريــة األمنيــة ومت‬\n     ‫القبــض علينــا قبــل أن تنــزل املــرأة ‪ ........‬وأطفالهــا مــن الشــقة وأمــا مــا‬\n     ‫ذكــره املدعــي العــام مــن عــدم التجــاوب مــع جهــة التحقيــق عنــد طلبــي‬\n     ‫فهــذا غيــر صحيــح فقــد كنــت أحضــر كلمــا طلبــت للحضــور وأمــا‬\n     ‫عــدم التجــاوب أثنــاء االســتجواب فهــذا صحيــح وســبب ذلــك أنــي ال‬\n     ‫أعــرف مــا هــي التهمــه املوجهــة لــي ولــم يقــم احملقــق بإخبــاري عــن التهمه‬\n     ‫املوجهــة لــي وقــام احملقــق بســؤالي أســئلة عــن عــدة قضايــا مختلفــة‬\n     ‫هكــذا أجابــت وأجابــت املدعــى عليهــا ‪........‬بقولهــا مــا جــاء يف الدعــوى‬\n     ‫العامــة مــن اشــتراكي مــع ‪........‬بإفســاد وتخبيــب املــرأة ‪........‬علــى‬\n     ‫زوجهــا وحتريضهــا علــى الهــروب بأبنائهــا الســعوديني القصــر هــذا غيــر‬\n     ‫صحيــح والصحيــح أنــه قبــل ســنه تقريب ـ ًا مــن القبــض علينــا أخبرتنــي‬\n     ‫صديقتــي ‪........‬بــأن املــرأة ‪........‬تعانــي من ضيق العيش وتطلب املســاعدة‬\n     ‫يف تأمــن الطعــام والشــراب فاتصلــت أنــا بهيئــة حقــوق اإلنســان بالدمــام‬\n     ‫وأخبرتهــم باملوضــوع ويظهــر بأنهــم عاجلــوا املشــكلة وقبــل القبــض‬\n     ‫علينــا بيــوم أخبرتنــي ‪ .....‬بــأن املــرأة ‪........‬قــد ســافر عنهــا زوجهــا ملــدة‬\n\n\n‫‪41‬‬\n\f‫خمســة أيــام وأقفــل بــاب الشــقة عليهــم وال يوجــد طعــام لهــا وألطفالهــا‬\n‫فقلــت لــ‪ ........‬بأنــه ال ميكــن مســاعدة ‪ .....‬وبــاب الشــقة مقفــل عليهــا‬\n‫فأخبرتنــي ‪ ........‬فيمــا بعــد بــأن ‪ ........‬أخبرتهــا بــأن لديهــا مفتــاح ســري‬\n‫ويف يــوم القبــض علينــا ذهبــت أنــا و‪ ........‬علــى ســيارة ســائقي إلى مكان‬\n‫ســكن املــرأة ‪........‬كــي نأخذهــا هــي وأطفالهــا معنــا للســوق لشــراء‬\n‫حاجياتهــا وكانــت ‪........‬تتحــدث مــع ‪........‬علــى اجلــوال ملعرفــة مــكان‬\n‫ســكنها وعندمــا وصلنــا إليــه يف حــي ‪........‬بالدمــام وقبل توقف ســيارتنا‬\n‫توقــف تــام حضــرت الدوريــة األمنيــة ومت القبــض علينــا قبــل أن تنــزل‬\n‫املــرأة ‪........‬وأطفالهــا مــن الشــقة وأمــا مــا ذكــره املدعــي العــام مــن عــدم‬\n‫التجــاوب مــع جهــة التحقيــق عنــد طلبــي فهــذا غيــر صحيــح فقــد كنــت‬\n‫أحضــر كلمــا طلبــت للحضــور وأمــا عــدم التجــاوب اثنــاء االســتجواب‬\n‫فهــذا صحيــح وســبب ذلــك أنــي ال أعــرف التهمــة املوجهــة لــي ولــم يقــم‬\n‫احملقــق بإخبــاري عــن التهمــه املوجهــة لــي وقــام احملقــق بســؤالي أســئلة‬\n‫عــن عــدة قضايــا مختلفــة هكــذا أجابــت وقــد حضــر يف هــذه اجللســة‬\n‫املدعــي اخلــاص ‪ ........‬ســعودي بالســجل املدنــي رقــم ‪ ........‬وأفهــم بــأن‬\n‫ســماع دعــواه يف احلــق اخلــاص ســيكون يف اجللســة القادمــة نظــر ًا لضيــق‬\n‫الوقــت وقــد جــرى تســليم كل واحــد مــن املدعــى عليهمــا واملدعــي‬\n‫اخلــاص صــورة الئحــة الدعــوى العامــة ثــم أقفلــت اجللســة الســاعة احلاديــة‬\n‫عشــر للتأمــل وأفهــم األطــراف باحلضــور يف يــوم األربعــاء‬\n         ‫‪1434/1/28‬الساعة التاسعة وصلى اهلل وسلم على نبينا محمد‬\n‫احلمــد هلل وحــده وبعــد ثــم إنــه يف هــذا اليــوم األربعــاء ‪1434/1/28‬ه ـ‬\n‫الســاعة التاســعة افتتحــت اجللســة وقــد حضــر املدعــي اخلــاص ‪........‬‬\n‫ولــم يحضــر املدعــى عليهمــا ‪........‬و‪ ........‬وبســؤال املدعــي اخلــاص‬\n\n\n                                                                                          ‫‪42‬‬\n\f     ‫عــن دعــواه قــال إنــه يف يــوم األحــد ‪1433/7/4‬ه ـ بعــد صــاة العصــر‬\n     ‫كنــت أمــارس الرياضــة بالقــرب مــن الســكن فاتصلــت بــي زوجتــي‬\n     ‫‪........‬تخبرنــي بــأن املدعــى عليهمــا ‪ ........‬و‪ ........‬ســوف حتضــران كــي‬\n     ‫يأخذونهــا مــع أطفالــي ويذهبــون بهــم إلــى الســفارة ‪ .....‬يف الريــاض‬\n     ‫فاتصلــت أنــا مباشــرة مــن جوالــي علــى الدوريــات وأبلغتهــم باملوضــوع‬\n     ‫فأخبرونــي بأنهــم ســوف يرســلون دوريــة للموقــع فذهبــت إلــى مقــر‬\n     ‫ســكني أنتظــر الدوريــة يف اخلــارج وقــد حضــرت الدوريــة بعــد ربــع‬\n     ‫ســاعة تقريبـ ًا فقــام رجــل األمــن بأخــذ إفادتــي وأخبرتــه باملوضــوع وبعــد‬\n     ‫تواصلــه مــع العمليــات طلــب منــي االنتظــار حتــى حتضــر املدعــى عليهمــا‬\n     ‫‪ ........‬و‪ ........‬للتأكــد مــن البــاغ فبقيــت أنتظــر مــع رجــل األمــن إلــى‬\n     ‫مغــرب ذلــك اليــوم ثــم حضــرت الســيارة التــي يركبهــا املدعــى عليهمــا‬\n     ‫‪........‬و‪ ........‬ويقودهــا الســائق وبعدمــا توقفــت ســيارتهما نزلــت زوجتــي‬\n     ‫معهــا أطفالــي وهــم ثالثــة أكبرهــم عمــره تســع ســنوات وقــت القضيــة‬\n     ‫ومــع زوجتــي شــنطتني واحــدة يوجــد بهــا مالبســها واألخــرى حتتــوي على‬\n     ‫مالبــس األطفــال فنــزل ســائق الســيارة ومعــه إحــدى املدعــى عليهمــا ال‬\n     ‫أدري مــن هــي بالضبــط وأخــذا الشــنطتني مــن زوجتــي ووضعوهــا يف‬\n     ‫شــنطة الســيارة وقــد ركــب اثنــان مــن أطفالــي يف الســيارة وقبــل أن‬\n     ‫تركــب زوجتــي الســيارة حضــرت مــع رجــل األمــن وأخرجــت أطفالــي‬\n     ‫مــن الســيارة وطلبــت مــن زوجتــي وأطفالــي العــودة للشــقة وبنــاء عليــه‬\n     ‫أطلــب تعزيــر املدعــى عليهمــا لقــاء محاولتهمــا تهريــب زوجتــي وأطفالــي‬\n     ‫إلــى جهــة خارجيــة وتخبيبهمــا زوجتــي علــي هــذه دعــواي ويف هــذا الوقت‬\n     ‫حضــرت املدعــى عليهمــا األولــى ‪........‬والثانيــة ‪........‬وبســؤال املدعــى‬\n     ‫عليهمــا عــن دعــوى املدعــي اخلــاص قالــت املدعــى عليهــا ‪........‬إن جوابــي‬\n\n\n‫‪43‬‬\n\f‫علــى دعــوى املدعــي اخلــاص ‪........‬هــو نفــس جوابــي علــى دعــوى املدعــي‬\n‫العــام املذكــور يف اجللســة الســابقة هكــذا أجابــت وأجابــت املدعــى‬\n‫عليهــا ‪........‬بقولهــا إن جوابــي علــى دعــوى املدعــي اخلــاص ‪........‬هــو نفــس‬\n‫جوابــي علــى دعــوى املدعــي العــام املذكــور يف اجللســة الســابقة هكــذا‬\n‫أجابــت وبســؤال املدعــى عليهــا ‪........‬عمــا ذكــره املدعــي العــام يف دعــواه‬\n‫مــن أنهــا طلبــت مــن ‪........‬زوجــة املدعــي جتهيــز شــنطة صغيــرة لــأوالد‬\n‫فقالــت املدعــى عليهــا ‪........‬نعــم عندمــا كنــت متجهــة مــع ‪........‬للمــرأة‬\n‫‪........‬كــي تركــب معنــا هــي وأطفالهــا ونشــتري حاجتهــا علمــت أن‬\n‫لديهــا طفــل رضيــع فطلبــت مــن ‪........‬أن تطلــب مــن ‪........‬جتهيــز شــنطة‬\n‫صغيــرة للطفــل الرضيــع حتتــوي علــى احلليــب والغيــار هكــذا قــررت‬\n‫كمــا جــرى ســؤال املدعــى عليهــا ‪........‬عمــا ذكــره املدعــي العــام يف‬\n‫دعــواه مــن أنهــا قابلــت املــرأة ‪........‬قبــل ســنه مــن القبــض عليهــا يف مجمــع‬\n‫‪........‬مــول وســلمت املــرأة ‪........‬جهــاز جــوال ومبلــغ خمســمائة ريــال ‪500‬‬\n‫داخــل دورة امليــاه فقالــت املدعــى عليهــا ‪........‬نعــم قابلــت املــرأة ‪........‬قبــل‬\n‫ســنه مــن القبــض علــي يف مجمــع ‪........‬مــول التجــاري ‪ ....‬وســلمتها جهــاز‬\n‫جــوال مــع شــريحته ومبلــغ خمســمائة ريــال داخــل دورة امليــاه وكان هــذا‬\n‫بعدمــا طلبــت والــدة ‪........‬منــي ذلــك حتــى تتمكــن ‪........‬من شــراء الغذاء‬\n‫لهــا وألطفالهــا وكــي تتواصــل مــع والدتهــا هكــذا قــررت ثــم جــرى‬\n‫ســؤال املدعــي العــام البينــة علــى دعــواه فقــال بينتــي مــا ذكــرت كمــا‬\n‫جــرى ســؤال املدعــي اخلــاص عــن بينتــه علــى الدعــوى فقــال بينتــي هــي‬\n‫مــا قدمــه املدعــي العــام وليــس لــدي أي زيــادة علــى بينــة املدعــي العــام‬\n‫ثــم أقفلــت اجللســة الســاعة العاشــرة والربــع لطلــب معــدي محضــر تنفيــذ‬\n‫املهمــة وأفهــم األطــراف باحلضــور يــوم الســبت ‪1434/4/20‬ه ـ الســاعة‬\n\n\n                                                                                             ‫‪44‬‬\n\f     ‫التاســعة وصلــى اهلل وســلم علــى نبينــا محمــد احلمــد هلل وحــده وبعــد ثــم‬\n     ‫إنــه يف هــذا اليــوم الســبت ‪1434/4/20‬ه ـ الســاعة التاســعة افتتحــت‬\n     ‫اجللســة بحضــور املدعــى عليهمــا ‪ ........‬و‪........‬ولــم يحضــر املدعــي اخلــاص‬\n     ‫‪........‬كمــا لــم يحضــر معــدي محضــر التنفيــذ وبنــاء عليــه فقــد أقفلــت‬\n     ‫اجللســة الســاعة التاســعة والربــع لطلــب معــدي محضــر تنفيــذ املهمــة‬\n     ‫يف يــوم الســبت ‪1434/6/3‬ه ـ الســاعة التاســعة وأفهــم املدعــى عليهمــا‬\n     ‫باحلضــور يف هــذا املوعــد وصلــى اهلل وســلم علــى نبينــا محمــد احلمــد‬\n     ‫هلل وحــده وبعــد ثــم إنــه يف هــذا اليــوم الســبت ‪1434/6/3‬ه ـ الســاعة‬\n     ‫التاســعة افتتحــت اجللســة بحضــور املدعــي اخلــاص ‪........‬واملدعــى عليهمــا‬\n     ‫‪........‬و‪........‬ولــم يحضــر معــدي محضــر التنفيــذ ثــم قــرر املدعــي اخلــاص‬\n     ‫‪........‬بقولــه إنــي ال أســتطيع إحضــار معــدي محضــر التنفيــذ هكــذا‬\n     ‫قــرر ثــم جــرى ســؤال املدعــى عليهمــا ‪........‬و‪........‬ملــاذا لــم تقومــا بإبــاغ‬\n     ‫الشــرطة عــن حالــة ‪........‬كــي تقــوم هــي باتخــاذ الــازم فقالــت ‪........‬‬\n     ‫لقــد لبينــا واجبـ ًا دينيـ ًا شــرعي ًا حــث عليــه الديــن اإلســامي ولــم يخطــر‬\n     ‫يف بالنــا اللجــوء للشــرطة لعــدم احلاجــة لذلــك مثــل أي جمعيــة خيريــه‬\n     ‫وليســت املــرة األولــى وال الوحيــدة التــي نقــوم مبســاعدتها هــي أو غيرهــا‬\n     ‫إذا جلــأ أحــد إلينــا هكــذا قــررت وقالــت املدعــى عليهــا الثانيــة ‪........‬‬\n     ‫لقــد لبينــا واجبـ ًا دينيـ ًا شــرعي ًا حــث عليــه الديــن اإلســامي ولــم يخطــر‬\n     ‫يف بالنــا اللجــوء للشــرطة لعــدم احلاجــة لذلــك مثــل أي جمعيــة خيريــه‬\n     ‫وليســت املــرة األولــى وال الوحيــدة التــي نقــوم مبســاعدتها هــي أو غيرهــا‬\n     ‫إذا جلــأ أحــد إلينــا هكــذا قــررت وعليــه فقــد أقفلــت اجللســة الســاعة‬\n     ‫التاســعة والثلــث لطلــب معــدي محضــر تنفيــذ املهمــة يف يــوم األربعــاء‬\n     ‫‪1434/8/3‬ه ـ الســاعة التاســعة وافهــم االطــراف باحلضــور يف هــذا‬\n\n\n‫‪45‬‬\n\f                                   ‫املوعــد وصلــى اهلل وســلم علــى نبينــا محمــد‬\n‫احلمــد هلل وحــده وبعــد ثــم إنــه يف هــذا اليــوم األربعــاء ‪1434/ 8/3‬ه ـ‬\n‫الســاعة التاســعة افتتحــت اجللســة بحضــور املدعــى عليهمــا ‪........‬و‪........‬‬\n‫واملدعــي اخلــاص ‪........‬ولــم يحضــر معــدي محضــر تنفيــذ املهمــة فجــرى‬\n‫الرجــوع إلــى اللفــة رقــم (‪)13‬وتضمنــت محضــر تنفيــذ املهمــة وقــد جــاء‬\n‫فيــه أنــه ورد بــاغ مــن املدعــي ‪........‬عــن حضــور املدعــى عليهمــا‬\n‫‪........‬و‪ ........‬لــه واالتصــال علــى زوجتــه ومحاولــة تهريبهــا وخطفهــا‬\n‫فحضــرت الدوريــة إلــى املبلــغ وعنــد االنتظــار معــه لوحظــت الزوجــة‬\n‫واألطفــال والعفــش معهــم نازلــن إلــى املدعــى عليهما حتى قرب الســيارة‬\n‫وبعدهــا تدخــل الــزوج وأبلــغ زوجتــه واألطفــال بالرجــوع إلــى الشــقة‬\n‫وبعــرض هــذا احملضــر علــى املدعــى عليهمــا قالــت ‪........‬الصحيــح أنــي‬\n‫عندمــا حضــرت مــع ‪........‬علــى ســيارة ســائقها إلــى منــزل ‪........‬زوج املــرأة‬\n‫‪........‬وعنــد توقــف ســيارتنا حضــرت الدوريــة األمنيــة لنــا مباشــرة قبــل‬\n‫خــروج املــرأة ‪........‬وأطفالهــا مــن الشــقة هكــذا قــررت وقالــت ‪........‬‬\n‫الصحيــح أنــي عندمــا حضــرت مــع ‪........‬علــى الســيارة التــي يقودهــا‬\n‫ســائقي إلــى منــزل ‪........‬زوج املــرأة ‪........‬وعنــد توقــف ســيارتنا حضــرت‬\n‫الدوريــة األمنيــة لنــا مباشــرة قبــل خــروج املــرأة ‪........‬وأطفالهــا مــن الشــقة‬\n‫هكــذا قــررت وبعــرض احملضــر علــى املدعــي ‪........‬قــال الصحيــح أنــي‬\n‫بعــد أن بلغــت الشــرطة حضــرت الدوريــة األمنيــة ثــم حضــرت الســيارة‬\n‫التــي يركــب بهــا املدعــى عليهمــا إلــى مــكان ســكني فنزلــت زوجتــي‬\n‫وأطفالــي مــن شــقتي وكان مــع زوجتــي حقيبتــان مالبــس لهــا ولألطفال‬\n‫وأخــذ ســائق ســيارة املدعــى عليهمــا احلقيبتان التي مــع زوجتي ووضعهما‬\n‫يف شــنطة ســيارته وكان أطفالــي متجهــن للركــوب يف الســيارة‬\n\n\n                                                                                           ‫‪46‬‬\n\f     ‫وعندهــا تدخلــت وطلبــت مــن زوجتــي وأطفالــي الرجــوع للشــقة هــذا مــا‬\n     ‫حصــل وبســؤال املدعــى عليهمــا عــن اجلــوال واملبلــغ املالــي الــذي مت‬\n     ‫تســليمه للمــرأة ‪........‬مــن قــام بالتكفــل بقيمتــه قالــت ‪........‬قمــت أنــا‬\n     ‫و‪ ........‬بتقاســم تكلفــة اجلــوال واملبلــغ املالــي الــذي ســلم ل‪ ........‬قبــل‬\n     ‫ســنه مــن القبــض علينــا حيــث دفعــت أنــا خمســمائة ريــال و‪........‬‬\n     ‫خمســمائة ريــال واشــترينا جهــاز جــوال بشــريحة ومت شــحنه مبائتــي‬\n     ‫ريــال وســلم للمــرأة ‪........‬مــع ثالثمائــة ريــال هكــذا أجابــت وقالــت ‪........‬‬\n     ‫لقــد تقاســمت أنــا و‪ ........‬قيمــة اجلــوال حيــث دفعــت أنــا خمســمائة ريــال‬\n     ‫و‪........‬خمســمائة ريــال واشــترينا اجلهــاز مــع شــريحته ومت شــحنه مبائتــي‬\n     ‫ريــال وســلم للمــرأة ‪........‬مــع ثالثمائــة ريــال كمــا جــرى ســؤالهما عــن‬\n     ‫ســبب تســجيلهما رقميهمــا علــى جهــاز اجلــوال املقــدم للمــرأة ‪........‬حيــث‬\n     ‫ذكرتــا ذلــك يف دفعهمــا املوضوعــي فقــال املدعــى عليهمــا ‪........‬و‪........‬‬\n     ‫حتــى تتصــل بنــا ‪........‬إذا احتاجــت للمســاعدة املاليــة هكــذا قررتــا‬\n     ‫كمــا جــرى ســؤالهما عــن نــص الرســالة التــي يذكــران بــأن املــرأة ‪........‬‬\n     ‫أرســلتها لهمــا قبــل حضورهمــا للمــرأة ‪........‬يف يــوم القبــض عليهمــا‬\n     ‫فقالــت ‪........‬إن نــص الرســالة مــدون يف الدفــع املوضوعــي الصفحــة‬\n     ‫الثالثــة وهــو (أنهــا محبوســة مــع أطفالهــا بــا مــأكل أو مشــرب وأنهــم‬\n     ‫يحتاجــون إلــى مســاعدة عاجلــة وأن زوجهــا غــادر إلــى بيشــة )وقالــت ‪......‬‬\n     ‫نــص الرســالة مــدون يف الدفــع املوضوعــي وهــو( أنهــا محبوســة مــع‬\n     ‫أطفالهــا بــا مــأكل أو مشــرب وأنهــم يحتاجــون إلــى مســاعدة عاجلــة‬\n     ‫وأن زوجهــا غــادر إلــى بيشــة ) هكــذا قررتــا وبســؤالهما هــل لديكمــا‬\n     ‫بينــة علــى أن رقــم اجلــوال الــذي صــدرت منــه هــذه الرســالة النصيــة يعــود‬\n     ‫للمــرأة ‪........‬قالــت ‪........‬شــريحة رقــم اجلــوال هــي الشــريحة التــي‬\n\n\n‫‪47‬‬\n\f‫أعطيناهــا للمــرأة ‪........‬وهــي بــدون اســم وقــد أرســلت لنــا ‪........‬مــن هــذا‬\n‫الرقــم رســائل نصيــة كثيــرة تطلــب مســاعدة غذائيــة وماليــة وليــس لدي‬\n‫بينــة خــاف مــا ذكــرت وقالــت ‪........‬شــريحة رقــم اجلــوال هــي الشــريحة‬\n‫التــي أعطيناهــا للمــرأة ‪........‬وهــي بــدون اســم وقــد أرســلت لنــا ‪........‬مــن‬\n‫هــذا الرقــم رســائل نصيــة كثيــرة تطلــب مســاعدة غذائيــة وماليــة وليس‬\n‫لــدي بينــة خــاف مــا ذكــرت هكــذا قررتــا وبســؤالهما كيــف وصلتما‬\n‫ملنــزل ‪........‬فأجابــت ‪........‬بقولهــا املــرأة ‪........‬هــي مــن قامــت بداللتنــا‬\n‫علــى املنــزل عــن طريــق اجلــوال الــذي أرســلت منــه الرســالة النصيــة‬\n‫املذكــورة التــي تطلــب فيهــا املســاعدة وأجابــت ‪........‬بقولهــا املــرأة ‪........‬‬\n‫هــي مــن قامــت بداللتنــا علــى املنــزل عــن طريــق اجلــوال الــذي أرســلت‬\n‫منــه الرســالة النصيــة املذكــورة التــي تطلــب فيهــا املســاعدة هكــذا‬\n‫أجابتــا وبســؤالهما هــل طلبتمــا مــن ‪........‬اخلــروج مــن الشــقة مــع أطفالهــا‬\n‫ومعهــا شــنط أثنــاء توجهكمــا لهــا فأجابــت ‪........‬بقولهــا اثنــاء توجهــي‬\n‫مع ‪........‬على ســيارة ســائقها إلى منزل ‪........‬زوج ‪........‬بعد ورود الرســالة‬\n‫التــي تطلــب فيهــا ‪........‬املســاعدة كنــت أحتــدث مــع ‪........‬علــى اجلــوال‬\n‫ألخــذ وصــف املنــزل فعلمــت ‪........‬أن ‪........‬لديهــا طفــل رضيــع فقالــت‬\n‫‪........‬لــي أطلبــي مــن ‪........‬جتهيــز شــنطة صغيــرة للطفــل الرضيــع كــي‬\n‫تخــرج ‪........‬وأطفالهــا وتركــب معنــا ونذهــب بهــا للســوق تشــتري‬\n‫حاجتهــا فطلبــت مــن ‪........‬ذلــك هكــذا أفــادت وقالــت ‪........‬عندمــا‬\n‫كنــت متجهــة مــع ‪........‬إلــى منــزل ‪........‬زوج ‪........‬بعــد ورود الرســالة‬\n‫التــي تطلــب فيهــا ‪........‬املســاعدة علمــت أن ‪........‬لديهــا طفــل رضيــع‬\n‫وكانــت ‪........‬تتحــدث مــع ‪........‬علــى اجلــوال فطلبــت مــن ‪ ......‬أن تخبــر‬\n‫‪........‬بتجهيــز شــنطة صغيــرة للرضيــع كــي تخــرج ‪........‬وأطفالهــا‬\n\n\n                                                                                         ‫‪48‬‬\n\f     ‫وتركــب معنــا ونذهــب بهــا للســوق تشــتري حاجتهــا هكــذا أفــادت بعــد‬\n     ‫ذلــك جــرى الرجــوع إلــى اللفــة رقــم (‪)40‬وتضمنــت ضبــط إفــادة املــرأة‬\n     ‫‪........‬زوجــة املدعــي اخلــاص ‪........‬وقــد جــاء فيهــا مــا ذكــره املدعــي العــام‬\n     ‫يف دعــواه ثــم جــرى االطــاع علــى األوراق املقيــدة باحملكمــة برقــم‬\n     ‫‪ 34/253120‬يف ‪ 1434/1/28‬ه ـ املقدمــة مــن املدعــى عليهمــا بشــأن‬\n     ‫دفوعهمــا الشــكلية وقــد جــاء فيهــا مــا نصــه «أو ًال ‪ :‬دفــع الدعــوى ‪:‬‬\n     ‫الدفــوع الشــكلية نؤكــد أن هــذه الدعــوى «كيديــة» ومفتعلــة وباطلــة‬\n     ‫مــع مــا فيهــا مــن إلهــاء وإشــغال للجهــاز القضائــي‪ ،‬كمــا أنهــا تفتقــر‬\n     ‫إلــى الكثيــر مــن شــروط الدعــوى املتفــق عليهــا يف القبــول وذلــك علــى‬\n     ‫النحــو التالــي‪1:‬ـ الدعــوى حســم أمرهــا منــذ أكثــر مــن عــام وبالتحديــد‬\n     ‫بتاريــخ ‪1432/7/4‬ه ـ بقــرار مــن ســمو أميــر املنطقــة‪ ،‬وكان اخلصمــان‬\n     ‫متواجــدان ولــم يحتــج املدعــي علــى أمــر ســمو أميــر املنطقــة‪ ،‬بــل وقــع‬\n     ‫عليــه بعــدم الرفــع لهيئــة التحقيــق واالدعــاء‪ ،‬وقــد مت ذلــك يف شــرطة‬\n     ‫‪ ........‬الدمــام‪ .‬وإننــا نــرى بــأن املدعــي األصيــل واالدعــاء العــام قــد أخفــوا‬\n     ‫هــذا األمــر عــن فضيلتكــم‪ ،‬وبذلــك تنطبــق عليهــم املــادة الثانيــة مــن‬\n     ‫الئحــة قواعــد احلــد مــن الشــكاوي الكيديــة والدعــاوي الباطلــة‪ ،‬يف‬\n     ‫مادتــه الثانيــة التــي تنــص علــى مــا يلــي‪ :‬املــادة الثانيــة (مــن قــدم شــكوى‬\n     ‫يف قضيــة منتهيــة بحكــم أو قــرار يعلمــه وأخفــاه يف شــكواه‪ ،‬فيجــوز‬\n     ‫إحالتــه للمحكمــة املختصــة لتقريــر تعزيــره) وكذلــك املــادة «الثانيــة‬\n     ‫والعشــرون» مــن نظــام اإلجــراءات اجلزائيــة ‪2‬ـ افتقارهــا إلــى املصلحــة‬\n     ‫املشــروعة التــي تعــود بالفائــدة علــى املدعــي فاملدعــي باحلــق اخلــاص ليــس‬\n     ‫لــه إال املضــارة فمصلحتــه اقتصاديــة‪ :‬يرمــي مــن ورائهــا احلصــول علــى‬\n     ‫حســنات احملســنني وشــخصية‪ :‬يرمــي مــن ورائهــا إحــراج ‪ ........‬أمــام‬\n\n\n‫‪49‬‬\n\f‫الــرأي العــام العاملــي مبواجهــة مــع ‪ ......‬مــن أجــل رفــع اســمه عــن الالئحــة‬\n‫الســوداء يف املنــع مــن الســفر ومــن دخــول األراضــي ‪ .....‬كمــا أن يف هــذه‬\n‫الدعــوى إضــرار بالقيــم اإلســامية النبيلــة التــي حتــث علــى إغاثــة‬\n‫امللهــوف بالتكافــل االجتماعــي واملســلم للمســلم كاجلســد الواحــد‪...‬‬\n‫ملــا تتضمنــه مــن عقوبــة جتــاه عمــل اخليــر ‪3‬ـ (يف املظهــر النظامــي‬\n‫لصحيفــة الدعــوى) ـ لــم يذكــر ســوى طرفــن مــن املدعــى عليهــم وغــاب‬\n‫الطــرف الثالــث (الســفارة ‪ )......‬حيــث مضمــون الدعــوى يصــرح‬\n‫مبشــاركة الطــرف الثالــث يف القضيــة مــع اســتحالة حدوثهــا دونــه‪،‬‬\n‫وكان علــى املدعــي العــام مخاطبــة احلكومــة ‪ .....‬حســب املــادة ‪ 31‬مــن‬\n‫اتفاقيــة فينــا للعالقــات الدبلوماســية املوقعــة عــام ‪ 1961‬والتــي تنــص‬\n‫أيض ـ ًا يف املــادة ‪ 41‬علــى (مــع عــدم املســاس باملزايــا واحلصانــات علــى‬\n‫األشــخاص الذيــن ميتعــون بهــا البعثــات الدبلوماســية احتــرام قوانــن‬\n‫ولوائــح الدولــة املعتمديــن لديهــا ‪ ،‬وعليهــم كذلــك واجــب عــدم التدخــل‬\n‫يف الشــؤون الداخليــة لتلــك الدولــة ‪ ،‬كل املســائل الرســمية املعهــود‬\n‫بحثهــا لبعثــة الدولــة املعتمــدة مــع الدولــة املعتمــدة لديهــا يجــب أن تبحــث‬\n‫مــع وزارة خارجيــة الدولــة املعتمــد لديهــا عــن طريقهــا أو مــع أي وزارة‬\n‫متفــق عليهــا) إن هــذه االتفاقيــة جتــرم التدخــل يف أي شــأن مــن شــؤون‬\n‫الدولــة املضيفــة وعليــه فقــد صرحــت الســفارة ‪ ......‬مــرار ًا احترامهــا‬\n‫لقوانــن البلــد مؤكــدة أنهــا تســتطيع تســفير مواطنتهــا فقــط وال ســلطة‬\n‫لهــا علــى أطفــال ســعوديني فهــل يعقــل أن تلجــأ الســفارة ‪ .....‬لنــا وتتجــاوز‬\n‫نظام ـ ًا دولي ـ ًا ووزارة بحجــم وزارة اخلارجيــة‪ ،‬بــل وعبــر تاريــخ اململكــة‬\n‫هــل حــدث مثــل هــذا الفعــل؟! ‪ ..‬أن ســفارة مــا خرقــت اتفاقيــة فينــا؟ ومــع‬\n‫ذلــك نطالــب باســتدعاء ممثــل الســفارة ‪ .....‬امتثــا ًال للمــادة (العشــرين)‬\n\n\n                                                                                         ‫‪50‬‬\n\f     ‫مــن نظــام اإلجــراءات اجلزائيــة‪4 .‬ـ يــورد املدعــي العــام مســتند ًا علــى‬\n     ‫املــادة ‪ 120‬بأنــه مت القبــض علينــا واإلفــراج عنــا عقــب التحقيــق بكفالة‬\n     ‫حضوريــة‪ ،‬وهــو ادعــاء باطــل وغيــر صحيــح‪ ،‬ومــا اســتخدام هــذه املــادة‬\n     ‫إال مــن قبيــل التضليــل لفضيلتكــم‪5 .‬ـ هــذه الدعــوى أمــر غيــر محتمــل‬\n     ‫الثبــوت بــل ال يقــره العقــل واملنطــق والعــرف بدليــل عــدم قــدرة املدعــن‬\n     ‫علــى تقــدمي أي قرينــة ذات قيمــة معتبــرة تؤكــد قــدرة امرأتــن (ال ميكن‬\n     ‫ـ نظامـ ًا ـ أن تقــودا ســيارة‪ ،‬باإلضافــة إلــى ـ نظامـ ًا أيضـاًـ اســتحالة ســفر‬\n     ‫أي إنســان عبــر وســائل مواصــات أخــرى دون إذن وكيلــه أو ولــي أمــره‬\n     ‫ال ســيما األجنبيــات) علــى اختطــاف أربعــة أشــخاص مــن الدمــام إلــى‬\n     ‫الســفارة ‪ ....‬بالريــاض‪ ،‬دون ترتيــب مســبق مــع الســفارة ولقــد راقبنــا‬\n     ‫عبــر اإلعــام احمللــي خــال الشــهر الفائــت مأســاة أطفــال املواطــن ‪........‬‬\n     ‫الــذي أعــدم يف العــراق وكيــف علــق األطفــال مــع جدهــم يف األردن حلني‬\n     ‫تســوية إجراءاتهــم الورقيــة بــن الســفارتني الشــقيقتني الســعودية‬\n     ‫واألردنيــة لنؤكــد عبــر هــذا املشــهد تعقــد اإلجــراءات (مرفــق خبــر‬\n     ‫األطفــال) لنــدرك مــدى ســفاهة التهمــة املوجهــة لنــا ‪6‬ـ أحــد املطالبــن‬\n     ‫باحلــق اخلــاص «‪ »........‬ال تتحــدث العربيــة ولــم يوضــح املدعــي العــام‬\n     ‫كيفيــة حصولــه علــى ادعاءاتهــا ممــا يثيــر الشــك لدينــا أنهــا اســتجوبت‬\n     ‫ا ال ســيما وأنهــا أعلنــت عبــر «اليوتيــوب» علــى االنترنــت أنهــا‬        ‫أص ـ ً‬\n     ‫تتعــرض للمحاكمــة مــع ســيدتني ال تعرفهمــا وال تــدري ملــاذا هــي يف‬\n              ‫ال (مرفق مقطع صوت وصورة لها مترجم للعربية)‬             ‫احملكمة أص ً‬\n     ‫‪7‬ـ هنــاك خطــأ يف بياناتــي أنــا «‪ »........‬فأنــا لســت مطلقــة ولســت موظفــة‬\n     ‫أهليــة ويف هــذا اســتهانة وارجتاليــة بينــة مــن املدعــي العــام بواجباتــه يف‬\n     ‫حتــري الدقــة يف ضبــط املعلومــة فضيلــة الشــيخ نريــد أن نثبــت أيضـ ًا يف‬\n\n\n‫‪51‬‬\n\f‫دفوعنــا األوليــة هنــا مســألتني األولــى ‪ :‬أن هيئــة التحقيــق واالدعــاء العــام‬\n‫لــم تتعامــل معنــا بشــكل شــرعي أو قانونــي أو نظامــي األمــر الــذي جــاء‬\n‫بنــا للمحكمــة ونحــن يف حالــة عــدم جــزم لســبب اســتدعائنا‪ .‬الثانيــة ‪:‬‬\n‫لقــد أخبرنــا احملضــر الضابــط «‪ »........‬ملــرات ثــاث أن املدعــي هــو ‪........‬‬\n‫ولكنــك قلــت أنــه ‪........‬ولــم تطلعنــا علــى خطــاب ‪........‬املوجــه لهيئــة‬\n‫التحقيــق واالدعــاء العــام ونأمــل أن نطلــع عليــه يف اجللســة القادمــة‪ .‬إننــا‬\n‫نــرى أن هــذه الدفــوع الشــكلية منفــردة ومجتمعــة‪ ،‬كافيــة لتبيــان‬\n‫بطــان هــذه الدعــوى الكيديــة» أه ـ ‪ .‬كمــا جــرى االطالع علــى األوراق‬\n‫املقيــدة باحملكمــة برقــم ‪ 34/959307‬يف ‪1434/4/20‬ه ـ املقدمــة مــن‬\n‫املدعــى عليهمــا بشــأن دفوعهمــا املوضوعيــة وجــاء فيهــا ما نصــه «احملور‬\n‫األول ‪:‬إن قيمنــا اإلســامية وخلفيتنــا احلقوقيــة تلزمنــا بتلبيــة أي نــداء‬\n‫مــن أي مســتغيثة بنــا إننــا ســيدتان ناشــطتان حقوقي ـ ًا ومعروفتــان علــى‬\n‫املســتوى احمللــي والعاملــي ولنــا موقــع علــى االنترنــت نتلقــى عبــره‬\n‫شــكاوى النســاء ونعالــج قضاياهــن عبــر القنــوات الرســمية احلكوميــة‬\n‫ولعلنــا عرفنــا علــى املســتويني بعــد جناحنــا يف قضيــة (‪........‬و‪........‬‬\n‫الشــهيرة بالطــاق لعــدم تكافــؤ النســب ) والتــي تبنيناهــا بشــكل‬\n‫كامــل ماليـ ًا ونفســي ًا وشــرعي ًا وحقوقيـ ًا ومتابعــة مــع الديــوان امللكــي‬\n‫واحملكمــة العليــا (مرفــق صــورة مــن موقعنــا والقضايــا التــي وردتنــا‬\n‫وعاجلنــا معظمهــا ) احملــور الثانــي ‪ :‬عالقتنــا بهــذه األســرة منــذ عــام‬\n‫‪ 2003‬ونحــن _ كناشــطات حقوقيــات _ نتابــع هــذه األســرة عبــر‬\n‫اإلعــام املرئــي واملقــروء حيــث كثــر ظهــور الرجــل وزوجتــه وكانــت‬\n‫األســرة حينهــا يف(بيشــة ) وكان يؤملنــا وضعهــا املالي املتــردي والقانوني‬\n‫املتشــعب املتســبب بــكل مشــاكلهم األســرية ولكــن لــم يكــن لنــا أي‬\n\n\n                                                                                       ‫‪52‬‬\n\f     ‫وســيلة اتصــال بهــم وحــن انتقلــوا إلــى الدمــام تواصلــت معنــا والــدة‬\n     ‫الزوجــة عــام ‪ 2010‬وألننــا صرنــا علــى قــرب غــدا أمــر تقــدمي املســاعدة‬\n     ‫املاليــة يســير ًا ممــا مكننــا مــن إيصــال هاتــف جــوال ومبلــغ مــن املــال‬\n     ‫للســيدة ‪........‬حســب طلــب والدتهــا التــي أكــدت أن الوضــع املالــي‬\n     ‫لزوجهــا عاجــز عــن توفيــر جهــاز خــاص البنتهــا بخاصيــة التصويــر‬\n     ‫لتتمكــن مــن رؤيــة أحفادهــا وطلبــت أرقــام حســاباتنا البنكيــة لكــي‬\n     ‫حتــول لنــا املبلــغ ولكنــا رفضنــا واعتبرنــا ذلــك مــن واجبنــا الدينــي‬\n     ‫واإلنســاني وهكــذا ســلمنا ‪........‬اجلــوال ( واملبلــغ كمــا فرضتــه والدتها‬\n     ‫وكان معــاد ًال ل ـ ‪ 300‬ريــال فقــط وزدنــا عليــه شــحن اجلــوال ب ـ ‪ 200‬ريــال‬\n     ‫وقــد ســجلنا لهــا علــى احملمــول شــريحة رقــم (‪ )........‬رقمينــا واحتفظنــا‬\n     ‫برقــم جوالهــا واتفقنــا أن تلجــأ إلينــا حــن تشــعر بحاجــة لذلــك ولــم‬\n     ‫تتصــل بنــا ‪........‬خــال عــام كامــل إال برســالتني نصيــة عبــر اجلــوال‬\n     ‫مضمونهمــا واحــد يفصــل بينهمــا شــهران تقريب ـ ًا لــم نســتجب لألولــى‬\n     ‫إلمياننــا بــأن الــزوج احلاصــل مؤخــر ًا علــى منــزل وســيارة ومبلــغ مــن املــال‬\n     ‫مــن الصدقــات كفيــل بــأن يلبــي احتياجــات أســرته أمــا الثانيــة‬\n     ‫فملخصهــا يقــول ‪ ( :‬أنهــا محبوســة مــع أطفالهــا بــا مــأكل أو مشــرب‬\n     ‫وأنهــم يحتاجــون الــى مســاعدة عاجلــة وأن زوجهــا غــادر إلــى بيشــة )‬\n     ‫وهــي الرســالة التــي كانــت مدعــاة لذهابنــا إليهــا لتلبيــة احتياجاتهــا‬\n     ‫الغذائيــة لهــا وألطفالهــا بعــد أن أكدنــا لهــا برســالة نصيــة أننــا ال‬\n     ‫ميكننــا مســاعدتها إن كان البــاب موصــد ًا كمــا ادعــت ولكنهــا‬\n     ‫أكــدت وعبــر رســالة نصيــة أيض ـ ًا أنهــا وجــدت مفتاحــا ســريا للبــاب‬\n     ‫وصــار مــا ســردناه أمامكــم يــا فضيلــة الشــيخ (مرفــق صــورة الرســالة‬\n     ‫وقــد نشــرت حينهــا يف صحيفــة ســبق اإللكترونيــة ) ونــود أن نضيــف‬\n\n\n‫‪53‬‬\n\f‫هنــا مــا أكدنــاه يف دفوعنــا الشــكلية مــن أن ‪........‬قــد دأب علــى إثــارة‬\n‫قضيتــه عبــر اإلعــام كلمــا خفــت صوتهــا لألهــداف التــي شــرحناها‬\n‫(مرفــق صــورة مــن صحيفــة عــكاظ عــام ‪ 2008‬يدعــي فيهــا نفــس‬\n‫االدعــاء علــى أم زوجتــه ) احملــور الثالــث وهــو األهــم تناقضــات وكــذب‬\n‫وحتريــف ألقوالنــا وصياغــة مســتعصية علــى الفهــم أحيان ـ ًا يف الئحــة‬\n‫االدعــاء وهــي كمــا يلــي ‪ /1:‬لقــد طلبنــا منكــم فضيلــة الشــيخ يف‬\n‫اجللســة الســالفة شــرح واســتيضاح مــا ورد علــى لســان املدعــي ‪........‬‬\n‫والــواردة يف منتصــف الســطر الرابــع مــن الصفحــة الثانيــة يف الئحــة‬\n‫االدعــاء ونصهــا (وتفاجــأت قبــل شــهرين أن ‪........‬نســقت مــع زوجتــه‬\n‫ملقابلــة ‪........‬يف مجمــع ‪........‬وقابلتهــا يف دورة امليــاه وأعطــت زوجتــه جهاز‬\n‫جــوال ومبلــغ ‪300‬ريــال ولــم يعــرف بهــذا اللقــاء إال بعــد بالغــه عــن‬\n‫املتهمتــن )ولكنــه استشــكل عليكــم تفســير قولــه تفاجــأت قبــل‬\n‫شــهرين ‪ ...‬ثــم يقــول أنــه لــم يعــرف بهــذا إال حلظــة البــاغ فوجهتم الســؤال‬\n‫ل‪ ........‬نفســه الــذي تلعثــم ولــم يســتطع أن يقــول ســوى أنــه ال يــدري مــن‬\n‫كتــب هــذه العبــارة ســبحان اهلل كاد املريــب أن يقــول خذونــي لطاملــا‬\n‫تســاءلنا ملــاذا يف هــذا اليــوم بالتحديــد تراســلنا ‪........‬اجلــواب علــى هــذا‬\n‫الســؤال يكمــن يف التناقــض الفاضــح يف الســطرين الذيــن طلبنــا‬\n‫اســتيضاحهما يف اجللســة الســابقة هــذا التناقــض يــدل داللــة أكيــدة‬\n‫علــى كــذب ‪........‬وعلــى تغاضــي املدعــي العــام عــن احلقيقــة كمــا أن‬\n‫فيــه مــا يجيــب علــى الســؤال بعاليــة ونشــرحه كالتالــي لعــل ‪........‬لــم‬\n‫تخبــر ‪........‬بأنهــا متلــك جــواال ً وقــد اكتشــف ‪........‬جــوال ‪........‬منــذ‬\n‫شــهرين قبــل احلادثــة وبــات يخطــط لكمــن يســتطيع عبــره إثــارة قضيــة‬\n‫عبــر اإلعــام لألســباب التــي شــرحناها يف دفوعنــا الشــكلية ولــذا قــام‬\n\n\n                                                                                       ‫‪54‬‬\n\f     ‫بإرســال الرســالة األولــى التــي لــم نســتجب لهــا فشــحذ ذهنــه أكثــر‬\n     ‫لتكــون الرســالة أقــوى حتفيــزا فامــرأة جائعــة ومحبوســة ال ميكــن ألي‬\n     ‫بشــر إال أن يقــدم علــى مســاعدتها ولذلــك نســتنتج أن الرســالتني قــد‬\n     ‫أرســلتا لنــا دون علــم ‪........‬وقــد أجبرهــا ‪........‬علــى الــرد علينــا لتصــف لنــا‬\n     ‫موقــع البنايــة دون أن تعــرف هــي الســبب وحيــث أننــا ال ننكــر تزويدنــا‬\n     ‫‪........‬باجلــوال واملبلــغ فإننــا نتســاءل ملــاذا جنحنــا يف ذلــك واســتطاعت‬\n     ‫هــي أن تخفــي املوضــوع ألشــهر ثمــان بينمــا لــم تســتطع إخفــاء أمــر‬\n     ‫تهريبهــا املزعــوم لثــوان معــدودة كمــا هــو مــدون يف الئحــة االدعــاء بعــد‬\n     ‫احلادثــة (املعنونــة مبحاولــة اختطــاف ‪........‬وأبنائهــا ) باشــرت علــى الفــور‬\n     ‫الســفارة ‪ .......‬أمــور مواطنتهــا وزارتهــا فمــا الــذي طلبتــه ‪........‬مــن‬\n     ‫ســفارتها إنهــا لــم تطلــب أي شــيء ســوى تأمــن وجبــات غذائيــة لهــا‬\n     ‫وألطفالهــا (مرفــق تصريحهــا لصحيفــة عــكاظ ) وكان األحــرى أن‬\n     ‫تطلــب منهــم إمتــام عمليــة التهريــب املزعومــة إال أن ‪ ........‬حقــق مرامــه‬\n     ‫وحصــل علــى وظيفــة بعــد احلادثــة مباشــرة وهــذا ممــا يســعدنا رغــم‬\n     ‫مكائــده ضدنــا مزيــد مــن الكــذب والتناقضــات يف الئحــة الدعــوى‬\n     ‫‪ -2‬يف إفــادة الــزوج يقــول ‪(........‬أن زوجتــه اتصلــت بــه وقالــت لــه أننــا‬\n     ‫قادمتــن إليهــا يف الطريــق ص ‪ 2‬س ‪) 8‬بينمــا تقــول الزوجــة يف الالئحــة‬\n     ‫(أن ‪........‬اتصلــت بهــا وأخبرتهــا أنهــا مــع ‪........‬عنــد املنــزل وأخبــرت‬\n     ‫زوجهــا ! ص ‪ 3‬س ‪)5‬فمتــى اســتطاع ‪........‬تقــدمي بــاغ وبــأي ســرعة‬\n     ‫خرافيــة متــت االســتجابة ! والصحيــح أن ‪........‬تفاجــأت باتصالنــا فهــي لــم‬\n     ‫ترســل لنــا الرســالة فاتصلــت بزوجهــا لتخبــره عــن هذا االتصــال املفاجئ‬\n     ‫‪ -3‬يتهمنــا ‪........‬بالتنســيق مــع زوجتــه لتهريبهــا ومعنــى ذلــك أنهــا موافقــة‬\n     ‫ومشــاركة يف التخطيــط فلمــاذا تفســد اخلطــة بإبــاغ زوجهــا؟؟‬\n\n\n‫‪55‬‬\n\f‫‪-4‬تذكــر الزوجــة أن إحــدى رســائلنا كانت(هــل أنــت لوحــدك يف‬\n‫املنــزل ص ‪ 3‬س ‪)2‬هكــذا كأول رســالة منــا! وال نــدري مــا هي مناســبة‬\n‫هــذا الســؤال إن كانــت لــم تراســلنا قبلــه ؟ وملــاذا نطرحــه عليهــا فجــأة‬\n‫وبعــد عــام ؟ كمــا تصــر ‪........‬علــى أنهــا لــم تــرد علــى رســائلنا ! ممــا‬\n‫يؤكــد عــدم رغبتهــا بالهــروب ! فكيــف يتــم التنســيق؟ وملــاذا يتــم‬\n‫ا مــع عــدم رغبتهــا ؟وكيــف نتوجــه إليهــا وهــي ال تســتجيب‬             ‫أص ـ ً‬\n‫لرســائلنا !؟‪ -5‬ورد يف الالئحــة أن ‪........‬أنكــرت أنهــا هــي مــن دلتنــا‬\n‫علــى شــقتها وتقــول أنهــا تعتقــد أن والدتهــا هــي مــن قــام بوصــف مــكان‬\n‫شــقتها ل‪ ........‬ص ‪ 3‬س ‪ !) 8‬فهــل يعقــل هــذا ؟؟ والدتهــا امــرأة يف ‪! ......‬‬\n‫تصــف لنــا موقــع شــقة! يف شــارع ! يف حــي لــم نرتــاده يوم ـ ًا ولــم نســمع‬\n‫عنــه! بينمــا احتجنــا للعديد من االتصاالت الهاتفية لنصل حملكمتكم‬\n‫املوقــرة إنــه ألمــر عجيــب و األعجــب منــه قبــول املدعــي العــام لهــذا‬\n‫الطــرح ! وعــدم توقــف فضيلتكــم أمامــه يقــول ‪........‬يف إفادتــه ( أن‬\n‫والــدة زوجتــه زارتهــم قبــل عشــر ســنوات ولــم يعجبهــا وضعهــم ص ‪ 2‬س‬\n‫‪)3‬كان ‪........‬وزوجتــه يف بيشــة قبــل عشــر ســنوات فكيــف لهــا أن‬\n‫تعــرف تفاصيــل أحيائنــا الدماميــة ؟ إن هــذا التصريــح مــن ‪........‬يؤكــد‬\n‫أمريــن األول ســوء الظــرف االقتصــادي الــذي تعيشــه األســرة والــذي‬\n‫يبــرر إقدامنــا علــى االســتجابة لرســالة امــرأة فقيــرة والثانــي كــذب‬\n‫‪........‬حيــث أن امــرأة تعيــش يف ‪ .....‬زارت ابنتهــا يف بيشــة ال ميكــن أن‬\n‫تصــف لنــا عنــوان شــقة يف حــي مغمــور يف أطــراف الدمــام! يــا فضيلــة‬\n‫الشــيخ لقــد قــال ‪........‬أمامــك أن زوجتــه لــم تــدع أن والدتهــا هــي مــن‬\n‫وصفــت البنايــة لنــا ولكــن هــذا االدعــاء مــدون يف الالئحــة كمــا‬\n‫تالحــظ فمــن الــذي اخترعــه!؟ كمــا أن ‪........‬أنكــر أن تكــون زوجتــه‬\n\n\n                                                                                     ‫‪56‬‬\n\f     ‫قالــت هــذا الــكالم وقــد أنكــر أيض ـ ًا أمامكــم اإلفــادة املتناقضــة‬\n     ‫املوجــودة يف الســطر الرابــع املشــار إليــه ! إنهــا أمــور تثيــر الدهشــة حيــث‬\n     ‫أننــا نعتقــد بــأن هــذا التناقضــات يف األقــوال ويف طريقــة تســجيل‬\n     ‫اإلجابــات غيــر الواضحــة لــكل مــن ‪........‬و‪........‬جتعلنــا نشــكك يف‬\n     ‫ا وذلــك مــا يدعــو إلــى‬ ‫ســامة إجــراءات التحقيــق معهمــا إن حدثــت أصـ ً‬\n     ‫إســقاط الالئحــة برمتهــا ولذلــك نرجــو مــن فضيلتكم أخذ شــكوكنا‬\n     ‫يف هــذا األمــر بعــن االعتبــار ‪ -‬يــرد يف الالئحــة أن ‪ .....‬تقــول( أن ليــس‬\n     ‫لديهــا مشــاكل وترغــب باالســتمرار بالعيــش مــع زوجهــا وأطفالنــا ص ‪3‬‬\n     ‫س ‪)9‬كمــا تقــول الالئحــة أنهــا (أنكــرت أنهــا ذكــرت ل‪ ........‬أو ‪........‬‬\n     ‫أنهــا جوعانــة أو محتجــزة وأن زوجهــا ســافر عنهــا ص ‪ 9‬س ‪)20‬األول‬\n     ‫ادعــاء كاذب فبعــد اجللســة األولــى انهمــرت شــكاواها عبــر النــت‬\n     ‫بالصــوت والصــورة حيــث أكــدت عوزهــم (وقــد زودناكــم بتلــك‬\n     ‫املقاطــع منســوخة مــن موقعهــا عبــر ذاكــرة إلكترونيــة صغيرة)أمــا‬\n     ‫االدعــاء الثانــي فهــي صادقــة بــه ألن مــن أرســل الرســالة هــو زوجهــا ودون‬\n     ‫علمهــا ‪ -7‬تدعــي الالئحــة علــى لســان ‪........‬قولهــا (أنهــا ال حتفــظ رقــم‬\n     ‫شــريحة اجلــوال ‪ ...‬كونــه عندمــا حصلــت املشــكلة رمــت الشــريحة ص‬\n     ‫‪ 2‬س ‪)19‬وســؤالنا هــو ‪ :‬هــل مــن عاقــل يتخلــص مــن أدلتــه ؟ وقــد كان‬\n     ‫مــن األجــدر أن نتخلــص نحــن مــن هــذا الرقــم املزعــج لنــا ولكنــا مــا زلنــا‬\n     ‫نحتفــظ بــه ‪ -8‬كمــا تــورد الالئحــة علــى لســان ‪(........‬أنهــا أطلعــت‬\n     ‫الشــرطة علــى الرســائل املرســلة إليهــا باللغــة االجنليزيــة ص ‪ 3‬س‪) 7‬‬\n     ‫ومبــا أن امللــف أمامــك يــا فضيلــة الشــيخ فإننــا نرجــو منــك اطالعنــا‬\n     ‫عليهــا يف هــذه اجللســة املنعقــد بتاريــخ ‪1414/4/20‬ه ـ ‪ -9‬ومــع إصــرار‬\n     ‫‪........‬علــى عــدم الــرد علــى رســائلنا حســب إفادتنــا إال أنهــا تؤكــد الــرد‬\n\n\n‫‪57‬‬\n\f‫علــى اتصالنــا الهاتفــي حيــث تــورد الالئحــة (ثــم اتصلــت ‪........‬وأخبرتهــا‬\n‫أنهــا مــع ‪........‬عنــد املنــزل وطلبــت النــزول مــع أطفالهــا والشــنط ألخذهــا‬\n‫وأطفالهــا وأخبــرت زوجهــا بذلــك ص ‪ 3‬س ‪ ) 5‬معنــى ذلــك أننــا كنــا‬\n‫ا مــع عــدم رغبتهــا‬  ‫عنــد بابهــا فمتــى أعــدت الشــنط ؟ وملــاذا تعدهــا أصـ ً‬\n‫يف الهــرب ؟ وملــاذا لــم تتجاهــل االتصــال كمــا جتاهلــت الرســائل ؟‬\n‫أليســت كل تلــك أســئلة حــري بــأن ميحصهــا املدعــي العــام وجديــرة بــأن‬\n‫تلفــت انتباهكــم يــا فضيلــة الشــيخ؟ ‪ -10‬يســتند املدعــي العــام يف أولــى‬\n‫نقاطــه علــى « محضــر تنفيــذ معــد مــن قبــل رجــال الدوريــة األمنيــة‬\n‫ويســرد تفاصيلهــا التــي مــن ضمنهــا ( مت مشــاهدة الزوجــة وأطفالهــا‬\n‫و»العفــش « ص ‪ 1‬س ‪ ) 16‬وكمــا نعلــم بــأن دور كل رجــل أمــن يكلــف‬\n‫بضبــط جنائــي هــو جمــع كل دليــل يؤكــد اجلرميــة إال أن رجــال األمــن‬\n‫لــم يجــدوا مــا ميكــن ضبطــه ألننــا نربــأ بهــم أيض ـ ًا عــن أن يكونــوا‬\n‫جاهلــن مبهمتهــم كمــا أن هيئــة التحقيــق واالدعــاء العــام لــم تتحــر‬\n‫حــول هــذه املســألة ولــم تأبــه مبســئوليتها حينمــا لــم يضبــط رجــال األمــن‬\n‫مــا ادعــوه مــن «عفــش» مزعــوم ! لقــد كان بإمــكان الدوريــة و‪........‬‬\n‫معهــم لــو كان واثق ـ ًا ممــا ادعــاه ضدنــا أن يتبعونــا بصمــت ليضبطونــا‬\n‫باجلــرم املشــهود ولكنهــم لــم يفعلــوا لثقتهــم التامــة جميعـ ًا بحســن نوايانا‬\n‫ونبــل هدفنــا وعليــه يكــون املدعــي ورجــا األمــن شــهود زور نطالــب‬\n‫بتعزيزهــم أشــد تعزيــر وقــد قال ســبحانه وتعالــى((وال تكتموا الشــهادة‬\n‫ومــن يكتمهــا فإنــه آثــم قلبــه )) وقــد رهــب الشــارع الكــرمي مــن شــهادة‬\n‫الــزور وجعلهــا يف مرتبــة اإلشــراك بــاهلل واعتبرهــا مــن أكبــر الكبائــر‬\n‫وهــدد مرتكبهــا بالويــل والثبــور اســتناد ًا إلــى قــول رســول اهلل صلــى‬\n‫اهلل عليــه وســلم ((أال أنبئكــم بأكبــر الكبائــر ؟ قلنــا بلــى يــا رســول‬\n\n\n                                                                                       ‫‪58‬‬\n\f     ‫اهلل قــال اإلشــراك بــاهلل وعقــوق الوالديــن وكان متكئـ ًا فجلــس وقــال‬\n     ‫أال وقــول الــزور أال وشــهادة الــزور فمــا زال يكررهــا حتــى قلنــا ليتــه‬\n     ‫ســكت‪11‬ورد يف الالئحــة يف صفحــة أقوالــي « أنــا ‪ (»........‬وأفــادت انهــا‬\n     ‫تتواصــل مــع املــرأة منــذ ســنة تقريب ـ ًا وتعرفــت عليهــا ‪........‬وتواصلــت‬\n     ‫معهــا وتعرفــت عليهــا املــرأة عــن طريــق ‪........‬ص ‪ 4‬س ‪ )17‬هنــا خطــأ‬\n     ‫لغــوي أو نحــوي واألصــح القــول أنــي تواصلــت (فعــل مــاض) ألن كل مــا‬\n     ‫دون مــن أقــوال ‪ ........‬يثبــت أن تواصلنــا معهــا لــم يتــم إال ملــرة واحــدة‬\n     ‫وقبــل عــام مــن احلادثــة أمــا بقيــة العبــارة فــكالم مهلهــل وغيــر مفهــوم‬\n     ‫حيــث ال يتضــح مــن عــرف مبــن ! ‪ -12‬ويــرد يف الالئحــة أيض ـ ًا وعلــى‬\n     ‫لســاني أن ‪ )........‬أخــذ أطفالــه وأركبنــي أنــا وزميلتــي الدوريــة ص ‪ 4‬س‬\n     ‫‪ )15‬وهــذا كــذب وادعــاء لــم أنطــق بــه ومــا حــدث هــو أن رجــال الدوريــة‬\n     ‫قالــوا لنــا اتبعونــا فركبنــا ســيارتنا وتبعنــا الدوريــة إلــى مركز الشــرطة‬\n     ‫بــكل ثقــة وال نــدري مــا مبــرر الكــذب ؟ ‪ -13‬ويــرد يف الالئحــة علــى‬\n     ‫لســاني أنــا « ‪ ........‬وممــا ال ميكــن أن أقولــه (‪ ...‬فتواصلــت مــع والدتهــا‬\n     ‫بعدهــا أعطتهــا األم ‪ ......‬رقــم جــوال ابتنهــا وتواصلــت معها عبر الرســائل‬\n     ‫كونهــا ال تســتطيع اســتخدام اجلــوال خوف ـ ًا مــن زوجهــا ص ‪ 3‬س ‪) 15‬‬\n     ‫حقيقــة ال نــدري كيــف يســتقيم ذلــك مــع طلــب والدتهــا منــا شــراء جوال‬\n     ‫لهــا وتســليمه لهــا حســب إفــادة ‪........‬وإفادتنــا !! وكيــف تكــون األم‬\n     ‫هــي مــن أعطتنــا الرقــم ! ونحــن مــن اشــتراه ! مــا زلنــا مندهشــات لســوء‬\n     ‫الصياغــة واألكاذيــب املتتاليــة!! ‪-14‬التخبيــب يــا فضيلــة الشــيخ ولــن‬\n     ‫نــزاود عليكــم يف تعريفــه لغــة واصطالحــا شــرعي ًا هــو إفســاد وتفســيد‬\n     ‫لعالقــة امــرأة بزوجهــا بخــداع وبالقــول املســتمر املنفــر مــن الــزوج إليغــار‬\n     ‫صــدر الزوجــة بذكــر مســاوئ الــزوج أو حتريضهــا علــى اخللــع والطــاق‬\n\n\n‫‪59‬‬\n\f‫وأخطــره حرام ـ ًا أن يفعــل ذلــك رجــل بامــرأة لغــرض الــزواج والــذي‬\n‫اعتبــره الفقهــاء مــن الكبائــر وأدنــاه يأتــي ألمــور تافهــة مــن رجــل أو‬\n‫امــرأة قريبــة أو أجنبيــة لغيــرة أو شــر يف نفســها وإذا جتاوزنــا احملــرم مــن‬\n‫التخبيــب والــذي ال ميكــن أن يلصــق بنــا حســب احلادثــة املزعومــة‬\n‫فالتخبيــب يحتــاج لزمــن ولنيــة كامنــة ولتواصــل مكانــي ولغــة‬\n‫مشــتركة واضحــة وحديــث يومــي ميكننــا مــن معرفــة ســوءات الــزوج‬\n‫لكــي نخببهــا عليــه بينمــا كل مــا نعرفــه أنهــا أســرة فقيــرة وحتتــاج‬\n‫مســاعدتنا هــي وزوجهــا وأطفالهــا وبذلــك تكــون تهمــة التخبيــب باطلــة‬\n‫ونضيــف إلــى ذلــك أن املــرأة لــم تــدع تخبيبـ ًا بــل تصــر علــى أنهــا لــم تــرد‬\n‫علــى أي رســالة منــا ال يف يــوم احلادثــة وال قبلهــا ولــم تــدع غيــر ذلــك‬\n‫حســب الئحــة املدعــي العــام وكل مــا حــدث هــو أننــا تعاملنــا معهــا مثلمــا‬\n‫نتعامــل مــع كل حالــة تلجــأ لنــا» أهــ‪ .‬وقــد قــررت ‪........‬و‪ ........‬بقولهــا ان‬\n‫هــذه هــي دفوعنــا املوضوعيــة والشــكلية علــى الدعــوى هكــذا قررتــا‬\n‫ثــم قالــت ‪........‬أود أن أضيــف بأنــه بعــد ورود رســالة ‪........‬التــي تطلــب‬\n‫فيهــا املســاعدة املاليــة والغذائيــة قمــت بإرســال رســائل نصيــة علــى‬\n‫اجلــوال ملديــر إدارة الدوريــات األمنيــة بالدمــام واملستشــار يف إمــارة‬\n‫املنطقــة الشــرقية الشــيخ ‪ ........‬وهيئــة احلقــوق اإلنســان وجمعيــة حقــوق‬\n‫اإلنســان ولــم جنــد التجــاوب منهــم هكــذا قــررت ثــم أقفلــت اجللســة‬\n‫الســاعة احلاديــة عشــر والنصــف للتأمــل وأفهــم األطــراف باحلضــور يــوم‬\n‫الســبت ‪1434/8/6‬ه ـ الســاعة التاســعة وصلــى اهلل وســلم علــى نبينــا‬\n                                                                                 ‫محمد‬\n‫احلمد هلل وحده وبعد ثم إنه يف هذا اليوم السبت ‪1434/8/6‬هـ الساعة‬\n‫التاســعة افتتحــت اجللســة بحضــور املدعــي اخلــاص ‪ ........‬واملدعــى عليهما‬\n\n\n                                                                                          ‫‪60‬‬\n\f     ‫‪ ........‬و‪ ........‬ثــم جــرى االطــاع علــى األوراق املقيــدة باحملكمــة برقــم‬\n     ‫‪ 34/1884764‬يف ‪1434/8/3‬ه ـ وعددهــا ســبع صفحــات ومــن ضمنهــا‬\n     ‫أربــع صفحــات صــور جلهــاز جوال وقالت املدعى عليهــا ‪........‬هذه األوراق‬\n     ‫تقدمــت بهــا وهــي تثبــت مــا ذكرتــه يف اجللســة الســابقة مــن قيامــي‬\n     ‫بإرســال رســائل نصيــة علــى اجلــوال ملديــر الدوريــات األمنيــة بالدمــام‬\n     ‫واملستشــار يف إمــارة املنطقــة الشــرقية الشــيخ ‪........‬وجمعيــة وهيئــة‬\n     ‫حقــوق اإلنســان بعــد ورود رســالة ‪........‬التــي تفيــد بأنهــا محبوســة مــع‬\n     ‫أطفالهــا بــا مــأكل أو مشــرب هكــذا قــررت كمــا جــرى الرجــوع إلــى‬\n     ‫اللفتــن رقــم (‪)63-58‬وجــاء فيهمــا محضريــن معديــن مــن قبــل احملقــق‬\n     ‫‪........‬حيــث جــاء يف احملضــر األول رفــض املدعــى عليهمــا االســتجواب‬\n     ‫وجــاء يف احملضــر الثانــي أنــه مت اســتدعاء ‪........‬جلهــة التحقيــق بفــرع‬\n     ‫الهيئــة فحضــرت وطلــب منهــا االنتظــار حلــن النــزول لغرفــة التحقيقــات‬\n     ‫ـاء علــى مــا تقــدم‬\n                         ‫النســائية وعنــد طلبهــا تبــن أنهــا غــادرت الهيئــة فبنـ ً‬\n     ‫مــن الدعــوى واإلجابــة وحيــث أقــرت املدعــى عليهمــا بقيامهمــا بتســليم‬\n     ‫املــرأة ‪........‬زوجــة املدعــي اخلــاص ‪........‬جهــاز جــوال بشــريحة ومبلــغ‬\n     ‫مالــي ســر ًا داخــل دورة ميــاه يف أحــد األســواق قبــل ســنه مــن القبــض‬\n     ‫عليهمــا وقــد حفظــا يف هــذا اجلهــاز املقــدم ل‪ ........‬رقمــي جوالهمــا ومــا‬\n     ‫دفــع بــه املدعــى عليهمــا مــن أن تســليمهما جهــاز اجلــوال للمــرأة ‪........‬‬\n     ‫بنــاء علــى طلــب والدتهــا كــي تــرى صــور أحفادهــا غيــر مقبــول فلــو‬\n     ‫كان لذلــك فــا حاجــة حلفــظ املدعــى عليهمــا رقمــي جوالهمــا يف اجلهــاز‬\n     ‫املقــدم للمــرأة ‪........‬ممــا يــدل علــى أن الهــدف هــو التواصــل مــع املــرأة‬\n     ‫‪........‬بــدون علــم زوجهــا ‪........‬والتدخــل يف حياتهمــا اخلاصــة وقــد أقــر‬\n     ‫املدعــى عليهمــا بأنــه كان يردهمــا رســائل نصيــة كثيــرة مــن هــذا‬\n\n\n‫‪61‬‬\n\f‫اجلــوال ويبعــد أن ال يتــم اجلــواب مــن قبــل املدعــى عليهمــا علــى الرســائل‬\n‫التــي تصــل لهمــا مــن املــرأة ‪........‬علم ـ ًا بأنــه يوجــد تناقــض يف إفــادة‬\n‫املدعــى عليهمــا حيــث أفادتــا يف اجللســة الســابقة بأنــه ورد لهمــا رســائل‬\n‫كثيــرة مــن جــوال ‪........‬الــذي قدمــاه لهــا بينمــا ذكرتــا يف دفعهمــا‬\n‫املوضوعــي بأنــه لــم يــرد مــن هــذا اجلــوال ســوى رســالتني نصيــة وهــذا‬\n‫بعيــد وحيــث أقــرت املدعــى عليهمــا بأنهمــا حضرتــا إلــى منــزل املدعــي‬\n‫اخلــاص ‪........‬وذلــك ألجــل أخــذ زوجتــه املــرأة ‪........‬وأطفالــه معهمــا وقــد‬\n‫أقرتــا بأنهمــا قــد طلبتــا مــن املــرأة ‪........‬جتهيــز شــنطة للطفــل الرضيــع‬\n‫كــي تخــرج املــرأة ‪........‬وأطفالهــا وتركــب معهمــا يف الســيارة وال شــك‬\n‫أن تواصــل املدعــى عليهمــا مــع املــرأة ‪........‬وطلبهمــا هــذا الطلــب منهــا‬\n‫دون علــم زوجهــا هــو ســعي إلفســاد املــرأة ‪........‬علــى زوجهــا وتخبيــب‬\n‫لهــا كمــا أنــه يوجــه التهمــة للمدعــى عليهمــا بتحريــض املــرأة ‪........‬علــى‬\n‫الهــرب بأطفالهــا وأمــا دفعهمــا بأنهمــا حضرتــا بعــد الرســالة النصيــة‬\n‫علــى اجلــوال مــن املــرأة ‪........‬فغيــر مقبــول حيــث ال بينــة علــى أن الرســالة‬\n‫املذكــورة قــد صــدرت مــن جــوال املــرأة ‪........‬وقــد نفــت املــرأة ‪........‬‬\n‫حتقيق ـ ًا أن تكــون ذكــرت للمدعــى عليهمــا أنهــا جائعــة أو محتجــزة‬\n‫أو أن زوجهــا ســافر عنهــا أو طلبــت منهمــا أخذهــا للســوبر ماركــت‬\n‫وأفــادت بــأن ‪........‬أرســلت لهــا ثــاث رســائل تفيــد بأنهــا ســتحضر‬\n‫وتأخذهــا للســفارة ‪ ......‬بالريــاض وعليهــا جتهيــز نفســها كمــا أنــه‬\n‫علــى فــرض صحــة ذلــك فهــذه الرســالة نصهــا كمــا أفــادت املدعــى‬\n‫عليهمــا هــو ((أنهــا محبوســة مــع أطفالهــا ال مــأكل أو مشــرب وأنهــم‬\n‫يحتاجــون إلــى مســاعدة عاجلــة وأن زوجهــا غــادر إلــى بيشــة)) فغايــة مــا‬\n‫تــدل عليــه هــذه الرســالة هــو طلــب الطعــام والشــراب وال يفهــم منهــا أن‬\n\n\n                                                                                         ‫‪62‬‬\n\f     ‫املــرأة ‪........‬تطلــب اخلــروج وأطفالهــا مــع املدعــى عليهمــا وميكــن تأمــن‬\n     ‫الطعــام والشــراب بعــد التواصــل مــع اجلهــات الرســمية حســب النظــام أو‬\n     ‫حتــى الذهــاب بالطعــام والشــراب لهــا مباشــرة بعــد معرفــة نــوع الطعــام‬\n     ‫املطلــوب وقــد تواصلــت املدعــى عليهمــا مــع املــرأة ‪........‬حســب مــا أفادتــا‬\n     ‫بــه كــي يعرفــان مقــر ســكنها فكيــف لــم يتــم التواصــل معهــا ملعرفــة‬\n     ‫الطعــام الــذي تريــده هــي وأطفالهــا دون طلــب خروجهــا وأطفالهــا‬\n     ‫معهمــا كمــا أن نــص الرســالة املذكــورة محــل نظــر فكيــف يقبــل‬\n     ‫أن يقــوم زوج بحبــس زوجتــه وأطفالــه ويســافر ويتركهــم دون طعــام‬\n     ‫أو شــراب فاملتعــن حينئــذ أن يطلــب مــن الزوجــة االتصــال باجلهــات‬\n     ‫الرســمية فوســيلة االتصــال موجــودة لديهــا أمــا الطلــب مــن املــرأة ‪........‬‬\n     ‫وأطفالهــا اخلــروج مــن املنــزل ومعهــا شــنطة للطفــل الرضيــع أثنــاء غيــاب‬\n     ‫الــزوج ودون علمــه فهــذا تخبيــب للمــرأة ‪........‬وتهمــة يف حتريضهــا علــى‬\n     ‫الهــرب مــع أطفالهــا والقبــول مبــا دفعــت بــه املدعــى عليهمــا يفتــح باب ـ ًا‬\n     ‫للفوضــى والشــر وجتــاوز النظــام وحيــث إن تخبيــب املــرأة علــى زوجهــا‬\n     ‫مــن كبائــر الذنــوب يقــول عليــه الصــاة والســام((ليس منــا مــن خبــب‬\n     ‫امــرأة علــى زوجهــا أو عبــدا علــى ســيده)) ويقــول صلــى اهلل عليــه وســلم‬\n     ‫((مــن خبــب زوجــة امــرئ أو مملوكــه فليــس منــا)) رواه أبــو داود قــال يف‬\n     ‫عــون املعبــود أي خدعهــا وأفســدها قــال يف االقنــاع ((وقــال ‪ -‬أي شــيخ‬\n     ‫اإلســام ‪ -‬يف رجــل خبــب امــرأة علــى زوجهــا يعاقــب عقوبــة بليغــة))‬\n     ‫كشــاف القنــاع عــن مــن االقنــاع ‪ 68/4‬وحيــث إنــه ال بينــة علــى عــدم‬\n     ‫جتــاوب املدعــى عليهمــا عنــد طلبهمــا فاحملضريــن املدونــن مــن قبــل‬\n     ‫احملقــق يــدالن علــى حضــور املدعــى عليهمــا عنــد طلبهمــا وأمــا عــدم‬\n     ‫اجابتهمــا علــى أســئلة احملقــق فهــذا يعــد نكــو ًال علــى اجلــواب وال‬\n\n\n‫‪63‬‬\n\f‫مســتند يف التعزيــر عليــه لــذا فقــد قــررت مــا يلــي أو ًال ثبــت لــدي قيــام‬\n‫املدعــى عليهمــا ‪........‬و‪ ........‬مبحاولــة تخبيــب املــرأة ‪........‬علــى زوجهــا‬\n‫املدعــي اخلــاص ‪........‬كمــا توجهــت التهمــة للمدعــى عليهمــا بتحريــض‬\n‫املــرأة ‪........‬زوجــة املدعــي اخلــاص ‪........‬علــى الهــرب بأطفالهمــا وقــررت‬\n‫تعزيــر املدعــى عليهمــا لقــاء مــا تقــدم بســجن كل واحــدة منهمــا مــدة‬\n‫عشــرة أشــهر اعتبــار ًا مــن تاريــخ إيقافهمــا خمســة أشــهر منهــا للحــق‬\n‫العــام وخمســة أشــهر للحــق اخلــاص باملدعــي ‪........‬ومنــع املدعــى عليهمــا‬\n‫مــن الســفر خــارج اململكــة مــدة ســنتني بعــد تنفيــذ محكوميتهمــا‬\n‫واملنــع مــن الســفر للحــق العــام ولــم يثبــت لــدي حتريــض املدعــى عليهمــا‬\n‫للمــرأة ‪........‬زوجــة املدعــي اخلــاص ‪........‬علــى الهــرب بأطفالهمــا ثاني ـ ًا‬\n‫لــم يثبــت لــدي أن املدعــى عليهمــا لــم يتجاوبــا مــع جهــة التحقيــق عنــد‬\n‫طلبهمــا وعــدم اســتحقاق املدعــى عليهمــا للتعزيــر علــى عــدم جتاوبهمــا‬\n‫اثنــاء اســتجوابهما ومبــا تقــدم حكمــت وبعــرض احلكــم لــم يقنــع‬\n‫املدعــى عليهمــا واســتعدا بتقــدمي الئحــة اعتراضيــة فأفهمــا مبراجعــة‬\n‫احملكمــة يــوم غــد األحــد ‪1434/8/7‬ه ـ الســتالم صــورة احلكــم‬\n‫وتقــدمي اعتراضهمــا خــال ثالثــن يومـ ًا ومــن ال تقدمــه خــال هــذه املــدة‬\n‫يســقط حقهــا يف االعتــراض وقــد قنــع املدعــي اخلــاص باحلكــم أمــا‬\n‫املدعــي العــام فلــم يقنــع باحلكــم مطالبـ ًا باالســتئناف مكتفيـ ًا مبــا قــدم‬\n‫يف الئحــة دعــواه وأقفلــت اجللســة الســاعة العاشــرة وصلــى اهلل وســلم‬\n‫علــى نبينــا محمــد احلمــد هلل وحــده وبعــد ثــم إنــه يف هــذا اليــوم الثالثــاء‬\n‫‪1434/ 9/8‬ه ـ الســاعة العاشــرة افتتحــت اجللســة وقــد جــرى االطــاع‬\n‫علــى الالئحــة االعتراضيــة املقدمــة مــن املدعــى عليهمــا ‪........‬و‪........‬‬\n‫املقيــدة باحملكمــة برقــم ‪34/2127332‬يف ‪1434/9/6‬ه ـ املكونــة‬\n\n\n                                                                                        ‫‪64‬‬\n\f     ‫مــن عشــر صفحــات مرفقـ ًا بهــا ســت صفحــات وذاكــرة فــاش مشــار ًا‬\n     ‫لهــا بالصفحــة العاشــرة مــن الالئحــة االعتراضيــة ولــم أجــد يف هــذه‬\n     ‫الالئحــة مــا يؤثــر علــى احلكــم وصلــى اهلل وســلم علــى نبينــا محمــد‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n     ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n     ‫لــدى احملكمــة برقــم ‪/34/2204971‬ج‪ 2‬وتاريــخ ‪1434/09/17‬ه ـ‬\n     ‫الــواردة مــن فضيلــة‪ /‬رئيــس احملكمــة اجلزائيــة مبحافظــة اخلبــر برقــم‬\n     ‫‪ 331536782‬وتاريــخ ‪1434/9/13‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n     ‫فضيلــة القاضــي باحملكمــة الشــيخ‪........ /‬املســجل برقــم ‪34288858‬‬\n     ‫كل‬ ‫ٍ‬    ‫وتاريــخ ‪1434/08/06‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‬\n     ‫مــن‪......../1‬و‪........ /2‬يف قضيــة االشــتراك بإفســاد وتخييــب الزوجــة‬\n     ‫علــى زوجهــا وحتريضهــا علــى الهــروب بأبنائهــا الســعوديني القصــر وقــد‬\n     ‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة‬\n     ‫القــرار وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا‬\n     ‫املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                      ‫وصحبــه وســلم‪ .‬حــرر يف ‪1434/10/ 27‬ه ـ ‪.‬‬\n\n\n\n\n‫‪65‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":32,"source_page_end":65,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"72863730c6b72a5ffcc28c3894988b318d2e865c8a4923f37b3e69c71ab06367","normalized_text_hash":"0bfe177a45434531b022ab4991f164bb2f590dc373046fa80c5dd5ec65aa10d5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p32-342288858"},{"id":"a77e63b7-6e5d-59b0-a462-09108eb5bfcc","document_type":"judgment","category":"judicial","subcategory":"general","title":"تغيب فتاة عن منزل أهلها -سفر فتاة دون محرم -اإلقرار بالتغيب والسفر -التعزير بالسجن واجللد -تعهد.","document_number":"33465824","case_number":"33598493","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف بدون الئحة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/27","year":"1434","subject":"تغيب فتاة عن منزل أهلها -سفر فتاة دون محرم -اإلقرار بالتغيب والسفر -التعزير بالسجن واجللد -تعهد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33465824 :‬تاريخه‪1434/11/27 :‬هـ‬\n                    ‫رقم الدعوى‪33598493 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 342609‬تاريخه‪1434/1/5 :‬هـ‬\n\n\n ‫تغيــب فتــاة عــن منــزل أهلهــا ‪ -‬ســفر فتــاة دون محــرم ‪ -‬اإلقــرار بالتغيــب‬\n                                ‫والســفر‪ -‬التعزيــر بالســجن واجللــد ‪ -‬تعهد‪.‬‬\n\n\n\n\n ‫قولــه صلــى اهلل عليــه وســلم كمــا يف حديــث عبــداهلل بــن عمــر رضــي‬\n          ‫اهلل عنهمــا‪« :‬ال تســافر املــرأة ثالثــة أيــام إال مــع ذي محــرم»‪.‬‬\n\n\n\n\n ‫أســفر التحقيــق عــن توجيــه االتهــام للمدعــى عليهــا بالتغيــب عــن منــزل‬\n ‫ذويهــا والســفر دون محــرم لغــرض ســيء ‪ ،‬طلــب املدعــي العــام إثبــات مــا‬\n ‫أســند إليهــا واحلكــم عليهــا بعقوبــة ‪ ،‬صادقــت علــى التغيــب عــن منــزل‬\n ‫أهلهــا أربعــة أشــهر وأنهــا ســافرت مبفردهــا إلــى الريــاض ومكثــت فيهــا‬\n ‫مــدة شــهر ثــم ســافرت إلــى اخلبــر ومكثــت فيهــا باقــي املــدة ودفعــت أن‬\n ‫ســبب خروجهــا مــن البيــت هــو حتــرش إخوانهــا وأخوالهــا بهــا‪ ،‬وأنهــا‬\n ‫ســبق وأن خرجــت مــن بيــت أهلهــا مرتــن قبــل ذلــك ‪ ،‬بعــرض ذلــك‬\n ‫علــى املدعــي العــام أجــاب أنــه ال علــم لــه مبــا دفعــت بــه املدعــى عليهــا‬\n ‫‪ ،‬بســؤال املدعــى عليهــا هــل لديهــا بينــة علــى مــا دفعــت بــه فأجابــت‬\n ‫أنــه ال بينــة لديهــا ‪ ،‬نظــر ًا ألن املدعــى عليهــا أقــرت بالتغيــب عــن منــزل‬\n ‫أهلهــا مــدة أربعــة أشــهر وألنهــا دفعــت أن ســبب تغيبهــا هــو مــا تتعــرض‬\n\n                                                                                        ‫‪66‬‬\n\f     ‫لــه مــن حتــرش مــن ذويهــا‪ ،‬وألن التغيــب املعاقــب عليــه هــو األصــل وال‬\n     ‫يعــدل عنــه إال لدليــل ظاهــر قــوي وال بينــة للمدعــى عليهــا علــى خالفــه‬\n     ‫لــذا ثبتــت إدانــة املدعــى عليهــا بالتغيــب عــن منــزل أهلهــا مــدة أربعــة‬\n     ‫أشــهر والســفر بــدون محــرم ومت احلكــم بســجنها مــدة ســتة أشــهر‬\n     ‫وأخــذ التعهــد عليهــا بعــدم العــودة ملثــل هــذا يف قــادم األيــام ‪ ،‬بعــرض‬\n     ‫احلكــم علــى املدعــي العــام قــرر اعتراضــه عليــه وطلــب رفــع املعاملــة إلــى‬\n     ‫محكمــة االســتئناف بــدون الئحــة‪ ،‬وقــررت املدعــى عليهــا قناعتهــا‪،‬‬\n                 ‫وبعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n     ‫اجلزائيــة‬\n        ‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة‬\n     ‫باألحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫اجلزائية يف محافظة االحساء برقم ‪ 33598493‬وتاريخ ‪1433/10/14‬هـ‬\n     ‫املقيــدة باحملكمــة برقــم ‪ 331795692‬وتاريــخ ‪1433/10/14‬ه ـ ففــي‬\n     ‫يوم األربعاء املوافق ‪1433/11/24‬هـ افتتحت اجللســة الســاعة ‪09 : 30‬‬\n     ‫وفيهــا حضــر املدعــي العــام ‪ ........‬املعمــد بالترافــع أمــام هــذه احملكمــة‬\n     ‫مبوجــب خطــاب ســعادة رئيــس دائــرة التحقيــق واالدعــاء العــام مبحافظــة‬\n     ‫اإلحســاء ذي الرقــم ه ـ ق ‪ 137/2/2‬والتاريــخ ‪1431/1/5‬ه ـ وادعــى‬\n     ‫علــى احلاضــرة معــه ‪ ........‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم‬\n     ‫‪ ........‬أنــه بتاريــخ ‪1433/10/5‬ه ـ مت اإلمســاك باملدعــى عليهــا مــن قبــل‬\n     ‫والدهــا أثنــاء مشــاهدتها لــه بداخــل مجمع(‪........‬مــول) وقــد تغيبــت عــن‬\n     ‫منزلــه ملــدة أربعــة أشــهر‪ .‬وبضبــط أقــوال والدهــا املدعو‪......../‬أفــاد بــأن‬\n     ‫املدعــى عليهــا ابنتــه كثيــرة التغيــب عــن املنــزل وســبق وأن ابلــغ عنهــا‬\n\n‫‪67‬‬\n\f‫بثــاث بالغــات رســمية وال يعــرف ســبب ًا واضحـ ًا لذلــك وبعــد مشــاهدته‬\n‫لهــا يف مجمــع ‪........‬مــول توجــه إليهــا فقاومتــه وحاولــت الهــرب منــه وقــرر‬\n‫عــدم رغبتــه يف اســتالمها‪ .‬وبضبــط أقوالهــا‪ /‬اعترفــت بخروجهــا مــن‬\n‫منــزل ذويهــا دون علــم منهــم وســافرت مبفردهــا إلــى الريــاض ومكثــت‬\n‫فيــه ملــدة شــهر ثــم بعــد ذلــك إلــى اخلبــر ومكثــت هنالــك باقــي فتــرة‬\n‫التغيــب ثــم قدمــت إلــى االحســاء ومت القبــض عليهــا مــن قبــل والدهــا‬\n‫مبجمــع(‪ ........‬مــول)‪ .‬وباالطــاع علــى املضبوطــات التــي بحوزتهــا‪ /‬تبــن‬\n‫بحوزتهــا (‪)4‬أربــع أجهــزه جــوال وجــد بداخلهــا أرقــام كثيــرة بــدون‬\n‫أســماء‪ ،‬وعــدد(‪ )5‬قصاصــات ورقيــه فيهــا أرقــام جــواالت‪ ،‬ووالعــة‬\n‫ســجائر‪ ،‬وعلبــه ســجائر وأقــرت املدعــى عليهــا بعائديــة املضبوطــات‬\n‫لهــا‪ .‬وقــد أســفر التحقيــق عــن توجيــه االتهــام لهــا بالتغيــب عــن منــزل‬\n‫ذويهــا والســفر دون محــرم لغــرض ســيء وذلــك لألدلــة والقرائــن التاليــة‬\n‫‪ -1 :‬اعترافهــا املــدون علــى الصفحــات (‪ )15-13‬مــن دفتــر االســتدالل‬\n‫املرفــق علــى اللفــة رقــم (‪-2 . )1‬ماجــاء يف أقــوال والدهــا املدعــو‪......../‬‬\n‫املنــوه عنــه واملــدون علــى الصفحتــن (‪ )11-10‬مــن دفتــر االســتدالل‬\n‫املرفــق علــى اللفــة رقــم (‪-3. )1‬محضــر القبــض املرفــق علــى اللفــة‬\n‫رقم(‪-4)3‬محضــر االطــاع علــى املضبوطــات املــدون علــى الصفحــة‬\n‫رقــم (‪)2‬مــن دفتــر التحقيــق املرفــق لفــه رقــم(‪ )11‬وحيــث إن مــا أقدمــت‬\n‫عليــه املذكــورة وهــي بكامــل أهليتهــا املعتبــرة شــرع ًا فعــل محــرم‬\n‫ومعاقــب عليــه شــرعا لــذا اطلــب إثبــات مــا أســند إليهــا واحلكــم عليهــا‬\n‫بعقوبــة تعزيريــة تزجرهــا وتــردع غيرهــا وتقــوم مــن ســلوكها‪ .‬هــذه‬\n‫دعــواي وبســؤال املدعــى عليهــا ‪........‬بحضــور املراقبــة ‪........‬والتــي قامــت‬\n‫بتطبيــق أوراق النزيلــة والتعريــف بهــا أجابــت قائلــة مــا ذكــره املدعــي‬\n\n\n                                                                                       ‫‪68‬‬\n\f     ‫العــام مــن أنــه بتاريــخ ‪1433/10/5‬ه ـ مت اإلمســاك بي مــن قبل والدي يف‬\n     ‫مجمــع ‪........‬مــول باألحســاء وذلــك ألننــي تغيبــت عــن منــزل أهلــي أربعــة‬\n     ‫أشــهر وأننــي ســافرت مبفــردي إلــى الريــاض ومكثــت فيهــا مــدة شــهر‬\n     ‫ثــم ســافرت إلــى اخلبــر ومكثــت فيهــا باقــي املــدة وأنهــم عثــروا بحوزتــي‬\n     ‫أربــع جــواالت ووالعــة ســجائر وعلبــة ســجائر فهــذا كلــه صحيــح جملــة‬\n     ‫وتفصيــا وكان ســبب خروجــي مــن البيــت هــو حتــرش إخوتــي وأخوالي‬\n     ‫بــي وســبق أن خرجــت مــن بيــت أهلــي مرتــن قبــل هــذا هكــذا أجابــت‬\n     ‫ا ال علــم لــي مبــا دفعــت بــه‬\n                                     ‫وبعــرض ذلــك علــى املدعــي العــام أجــاب قائـ ً‬\n     ‫املدعــى عليهــا هكــذا أجــاب وبســؤال املدعــى عليهــا هــل لديهــا بينــة‬\n     ‫ـاءا‬\n      ‫علــى مــا دفعــت بــه أجابــت قائلــة ليــس لــدي بينــة هكــذا أجابــت فبنـ ً‬\n     ‫علــى مــا تقــدم مــن الدعــوى واإلجابــة وإقــرار املدعــى عليهــا بالتغيــب‬\n     ‫عــن منــزل أهلهــا مــدة أربعــة أشــهر وحيــث إن املدعــى عليهــا دفعــت‬\n     ‫بــأن ســبب تغيبهــا هــو مــا تتعــرض لــه مــن حتــرش مــن ذويهــا وحيــث إن‬\n     ‫التغيــب املعاقــب عليــه هــو األصــل وال يعــدل عنــه إال لدليــل ظاهــر قــوي‬\n     ‫وال بينــة للمدعــى عليهــا علــى خالفــه ولقــول النبــي صلــى اهلل عليــه وســلم‬\n     ‫كمــا يف حديــث عبــداهلل بــن عمــر رضــي اهلل عنهمــا‪ « :‬ال تســافر املــرأة‬\n     ‫ثالثــة أيــام إال مــع ذي محــرم» لذلــك كلــه فقــد ثبــت لــدي إدانــة املدعــى‬\n     ‫عليهــا بالتغيــب عــن منــزل أهلهــا مــدة أربعــة أشــهر والســفر بــدون محــرم‬\n     ‫وحكمــت عليهــا مبــا يلــي ‪ :‬أوال‪ :‬ســجن املدعــى عليهــا مــدة ســتة أشــهر‬\n     ‫يحتســب منهــا مــدة بقائهــا بالســجن بخصــوص هــذه القضيــة ثانيــا‪:‬‬\n     ‫أخــذ التعهــد علــى املدعــى عليهــا بعــدم العــودة ملثــل هــذا يف قــادم األيــام‬\n     ‫هــذا مــا ظهــر لــي وبــه حكمــت وبعــرض ذلــك علــى املدعــي العــام قــرر‬\n     ‫اعتراضــه عليــه وطلــب رفــع املعاملــة إلــى محكمــة االســتئناف بــدون‬\n\n\n‫‪69‬‬\n\f‫الئحــة فأجبتــه لطلبــه وأمــا املدعــى عليهــا فقــررت قناعتهــا وبــه ختمــت‬\n‫اجللســة يف متــام الســاعة ‪ 10.00‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر يف ‪1433/11/24‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/ 33/2262721‬ج‪ 2‬وتاريــخ ‪1433/12/28‬ه ـ‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء برقــم‬\n‫‪ 331891371‬وتاريــخ ‪1433/12/20‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ ‪ ........ /‬املســجل برقــم ‪33465824‬‬\n‫وتاريــخ ‪1433/11/27‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪......../‬يف‬\n‫قضيــة تغيــب عــن منــزل ذويهــا والســفر دون محــرم وقــد تضمــن القــرار‬\n‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة‬\n‫ضبطه وأوراق املعاملة قررنا املصادقة على احلكم‪ .‬واهلل املوفق وصلى‬\n     ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/1/5‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                         ‫‪70‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":66,"source_page_end":70,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"11b0e00b31da5428ea8e7bb46d694d473ef24d550c1aa9173012947341fa1187","normalized_text_hash":"7911061f96b76d304e194953fda78ad1580889e9af92672ba041c0cba7c54548","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p66-33465824"},{"id":"69ef7b90-8807-518e-ab0a-11ca224102ba","document_type":"judgment","category":"judicial","subcategory":"general","title":"زنا -تغييب فتاة عن ذويها واخللوة بها ،إقرار ،إدانة ،تعزير بالسجن واجللد ،إبعاد .","document_number":"34285562","case_number":"34284388","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/2","year":"1434","subject":"زنا -تغييب فتاة عن ذويها واخللوة بها ،إقرار ،إدانة ،تعزير بالسجن واجللد ،إبعاد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34285562 :‬تاريخه‪1434/8/2 :‬هـ‬\n                        ‫رقم الدعوى‪34284388 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34302127‬تاريخه‪1434/5/4 :‬هـ‬\n\n\n     ‫زنــا ‪ -‬تغييــب فتــاة عــن ذويهــا واخللــوة بهــا ‪ ،‬إقــرار ‪ ،‬إدانــة ‪ ،‬تعزيــر‬\n                                                     ‫بالســجن واجللــد ‪ ،‬إبعــاد ‪.‬‬\n\n\n\n\n                                            ‫‪ -1‬قوله تعالى ( وال تقربوا الزنا ) ‪.‬‬\n     ‫‪ -2‬قولــه صلــى اهلل عليــه وســلم ( املســلم مــن ســلم املســلمون مــن لســانه‬\n                                                                            ‫ويــده ) ‪.‬‬\n     ‫‪ -3‬وقولــه صلــى اهلل عليــه وســلم ( ال يخلــون رجــل بامــرأة إال كان‬\n                                                           ‫الشــيطان ثالثهمــا ) ‪.‬‬\n\n\n\n\n     ‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه بإقامــة عالقــة‬\n     ‫غيــر شــرعية بفتــاة وتغييبهــا عــن منــزل ذويهــا وإيوائــه لهــا ‪ ،‬واالختــاء‬\n     ‫بهــا وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة رادعــة‬\n     ‫حيــث تقــدم أحــد املقيمــن بــأن ابنتــه البالغــة مــن العمــر ســبعة عشــر‬\n     ‫عامــا تغيبــت عــن املنــزل وبالبحــث عنهــا تبــن بأنهــا موجــودة لديــه ‪،‬‬\n     ‫أقــر املدعــى عليــه أمــام احملكمــة بالدعــوى ‪ ،‬ثبــت لــدى احملكمــة‬\n     ‫إدانــة املدعــى عليــه وقــررت تعزيــره بالســجن عشــرة أشــهر اعتبــار ًا‬\n     ‫مــن تاريــخ إيقافــه يف هــذه القضيــة وجلــده ســتني جلــدة تكــرر عليــه‬\n\n‫‪71‬‬\n\f‫خمــس مــرات بــن كل مــرة واألخــرى مــدة ال تقــل عــن أســبوع وذلــك‬\n‫للحــق العــام وبذلــك حكمــت ‪ ،‬كمــا أوصــت بإبعــاده خــارج اململكــة‬\n‫بعــد انتهــاء تنفيــذ عقوبتــه وعــدم الســماح لــه بالعــودة إال مــا تســمح بــه‬\n‫تعليمــات احلــج والعمــرة ‪ ،‬قــرر املدعــى عليــه القناعــة باحلكــم بينمــا‬\n‫اعتــرض املدعــى العــام بالئحــة فأفهــم بتعليمــات االســتئناف ‪ ،‬صــدق‬\n                                          ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد فلــدي‬\n‫ـاء علــى املعاملــة احملالــة‬\n                           ‫أنــا ‪ ...........‬القاضــي باحملكمــة اجلزئيــة بجــدة بنـ ً‬\n‫لنــا مــن فضيلــة الرئيس املســاعد برقــم ‪ 34284388‬يف ‪1434/06/20‬هـ‬\n‫فعليــه حضــر املدعــي العــام (‪ )........‬نيابــة عــن املدعــي العــام (‪)........‬‬\n‫مبوجــب التعميــد رقــم (‪ )........‬يف ‪1432/1/16‬ه ـ وادعــى علــى (‪)........‬‬\n‫(‪ )22‬عام ـ ًا مينــي اجلنســية ‪ ،‬مبوجــب البطاقــة البديلــة رقــم (‪)........‬‬\n‫موقــوف بســجون محافظــة جــدة مبوجــب أمــر التوقيــف رقــم (‪)........‬‬\n‫وتاريــخ ‪1434/6/1‬ه ـ ومــدد توقيفــه بســجون محافظــة جــدة مبوجــب‬\n‫أمــر التمديــد رقــم ‪...........‬وتاريــخ ‪1434/6/5‬ه ـ اســتناد ًا للمــادة (‪)108‬‬\n‫مــن نظــام اإلجــراءات اجلزائيــة حيــث انــه بتاريــخ ‪1434/5/23‬ه ـ تقــدم‬\n‫املقيــم‪........... /‬عــن تغيــب ابنتــه ‪ )17(........... /‬عــام عــن املنــزل وجــرى‬\n‫البحــث عنهــا واتضــح بأنهــا متواجــدة لــدى املدعــو‪........... /‬والــذي‬\n‫يعمــل حــارس بإحــدى العمائــر بحــي ‪...........‬ومت االنتقــال إلــى ذلــك‬\n‫املوقــع وطــرق البــاب وفتــح املذكــور أعــاه ومت القبــض عليــه ووجــدت‬\n‫الفتــاة املتغيبــة معــه بالغرفــة وقبــض عليهــا وســلمت لوالدهــا باســتجواب‬\n\n                                                                                          ‫‪72‬‬\n\f     ‫املتهــم املذكــور أفــاد بأنــه تعــرف علــى الفتــاة منــذ ســنه ونصــف وتقــدم‬\n     ‫خلطبتهــا مــن والدهــا ثــاث مــرات إال انــه رفــض وقامــت ابنتــه باخلــروج‬\n     ‫مــن املنــزل وقابلهــا أمــام ســوبر ماركــت ‪...........‬وأخذهــا إلــى غرفتــه‬\n     ‫وبقيــت لديــه حتــى قبــض عليهمــا وأنكــر التعــرض لهــا بــأي ســوء‬\n     ‫وأنكــر حتريضهــا علــى اخلــروج مــن منــزل أهلهــا أو فعــل الفاحشــة بهــا‬\n     ‫وأفــاد انــه ســوف يأخذهــا للســفارة للــزواج منهــا وبســماع أقــوال الفتــاة‬\n     ‫‪.........../‬أقــرت بأنهــا خرجــت مــن منــزل أهلهــا وقابلــة املدعــو‪........... /‬‬\n     ‫أمــام ســوبر ماركــت ‪...........‬وذهبــت معــه إلــى غرفتــه وبقيــت حتــى‬\n     ‫قبــض عليهــا معــه وانــه لــم يفعــل معهــا شــي حتــى قبــض عليهــا وانــه‬\n     ‫ســبق وان تقــدم خلطبتهــا إال أن والدهــا رفضــه وبالبحــث عــن ســوابقه لــم‬\n     ‫يعثــر لــه علــى ســوابق وقــد انتهــى التحقيــق إلــى توجيــه االتهــام للمذكــور‬\n     ‫بإقامــة عالقــة غيــر شــرعية بفتــاة وتغيبهــا عــن منــزل ذويهــا وإيوائــه لهــا‬\n     ‫‪ -‬واالختــاء بهــا ‪ -‬وذلــك لألدلــة والقرائــن التاليــة‪ -2:‬مــا جــاء باقــراره‬\n     ‫بالتحقيــق املرفــق لفــه (‪ -3 )14‬مــا جــاء مبحضــر القبــض املــدون صفحــه‬\n     ‫رقــم (‪ )3-2‬املــدون بدفتــر االســتدالل املرفــق لفــه (‪ )9‬وحيــث إن مــا‬\n     ‫أقــدم عليــه املتهــم املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب‬\n                  ‫إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة رادعــة ‪.‬‬\n     ‫ففــي هــذا اليــوم الثالثــاء املوافــق ‪1434/08/02‬ه ـ افتتحــت اجللســة‬\n     ‫الســاعة الثانيــة ونصــف وفيهــا حضر‪...........‬وبســؤاله عــن دعــوى املدعــي‬\n     ‫العــام أجــاب قائــا مــا ذكــره املدعــي العــام كلــه صحيــح جملــة‬\n     ‫وتفصيــا فقــد أقمــت عالقــة غيــر شــرعية مــع فتــاة ال متــت لــي بصلــة‬\n     ‫وغيبتهــا عــن منــزل أهلهــا مــدة خمســة أيــام وآويتهــا يف منزلــي إال أننــي‬\n     ‫لــم أتعــرض لهــا بــأي شــي ولــم أفعــل معهــا الفاحشــة وأنــا نــادم علــى هــذا‬\n\n\n‫‪73‬‬\n\f‫الفعــل وتائــب إلــى اهلل تعالــى هكــذا أجــاب ثــم جــرى الرجــوع إلــى أوراق‬\n‫املعاملــة واالطــاع علــى أقــوال املدعــى عليــه املدونــة علــى دفتــر التحقيــق‬\n‫لفــة رقــم (‪ )14‬واالطــاع علــى محضــر القبــض لفــة رقــم (‪ )9‬وهمــا‬\n‫مطابقــان ملــا جــاء يف إجابــة املدعــى عليــه فبنــاء علــى مــا تقــدم واإلجابــة‬\n‫وحيــث صــادق املدعــى عليــه علــى مــا جــاء يف دعــوى املدعــي العــام وأقــر‬\n‫بإقامتــه عالقــة محرمــة مــع الفتــاة وتغيبهــا عــن منزلهــا وألنــه ال عــذر‬\n‫ملــن أقــر علــى نفســه ولقولــه تعالــى ( وال تقربــوا الزنــا ) وقولــه صلــى اهلل‬\n‫عليــه وســلم ( املســلم مــن ســلم املســلمون مــن لســانه ويــده ) وقولــه صلــى‬\n‫اهلل عليــه وســلم ( ال يخلــو رجــل بامــرأة إال كان الشــيطان ثالثهمــا )‬\n‫ا قبيحـ ًا وجــرأة يف‬ ‫وألن مــا أقــدم عليــه املدعــى عليــه يعــد محرمـ ًا وفعـ ً‬\n‫الباطــل وإشــاعة للفاحشــة بــن املســلمني ويســتحق عليــه العقوبــة ولــكل‬\n‫مــا تقــدم فقــد ثبــت لــدي إدانــة املدعــى عليــه ‪ ...........‬بإقامــة عالقــة‬\n‫محرمــة مــع فتــاة وتغييبهــا عــن منــزل أهلهــا وإيوائهــا واالختــاء بهــا‬\n‫وقــررت تعزيــره بالســجن مــدة عشــرة أشــهر اعتبــار ًا مــن تاريــخ إيقافــه يف‬\n‫هــذه القضيــة وجلــدة ســتني جلــده تكــرر عليــه خمــس مــرات بــن كل‬\n‫مــرة واألخــرى مــدة ال تقــل عــن أســبوع وذلــك للحــق العــام وبــه حكمــت‬\n‫كمــا أوصــي بإبعــاده خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبتــه وعــدم‬\n‫الســماح لــه بالعــودة إال مــا تســمح بــه تعليمــات احلــج والعمــرة وبعــرض‬\n‫احلكــم علــى املدعــى عليــه قــرر قناعتــه باحلكــم وأبــدى املدعــي العــام‬\n‫اعتراضــه فأفهمتــه بــأن لــه مهلــة ثالثــن يوم ـ ًا مــن هــذا اليــوم لتقــدمي‬\n‫الئحتــه االعتراضيــة فــإن قدمهــا ســقط حقــه يف تقــدمي الالئحــة ورفعــت‬\n‫لالســتئناف بــدون الئحــة ففهــم ذلــك وكان ختــام اجللســة الســاعة الثالثة‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلى آلــه وصحبه أجمعني‬\n\n\n                                                                                        ‫‪74‬‬\n\f                                                          ‫حــرر يف ‪1434/08/02‬ه ـ‬\n     ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪ ...‬نحــن رئيــس‬\n     ‫وقضــاة الدائــرة اجلزائيــة الرابعــة يف محكمــة االســتئناف مبنطقــة‬\n     ‫مكــة املكرمــة جــرى منــا االطــاع علــى القــرار رقــم ‪34285562‬‬\n     ‫وتاريــخ ‪1434/8/2‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ ........... /‬القاضــي‬\n     ‫باحملكمــة اجلزائيــة بجــدة ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد‪/‬‬\n     ‫‪ ...........‬مينــي اجلنســية ‪ ،‬املتهــم بإقامــة عالقــة غيــر شــرعية بفتــاة وتغيبهــا‬\n     ‫عــن منــزل ذويهــا‪ ،‬احملكــوم فيــه مبــا دون باطنــه ‪ .‬وبدراســة القــرار‬\n     ‫وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة علــى احلكــم ‪،‬‬\n     ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪75‬‬\n\f76\n\f77\n\f78\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":71,"source_page_end":78,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8ca3ffbadb32a6481946adaf394fc4120068a8bb28364a87799c9440de9afa94","normalized_text_hash":"591994cb5982d6ee4d49ec9e840a7de51baa7f9318ca34237c453beb1ee81b10","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p71-34285562"}]$archive_payload$::jsonb AS data)
